def parse_prompts(etc_folder):
        """ Read prompts and prompts-orignal and return as dictionary (id as key). """
        from pathlib import Path

        prompts_path = Path(etc_folder) / "prompts"
        original_path = Path(etc_folder) / "prompts-original"

        result = {}

        def _load(file_path, key_name):
            if not file_path.is_file():
                return
            with file_path.open(encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.split(maxsplit=1)
                    if len(parts) != 2:
                        continue
                    pid, text = parts
                    entry = result.setdefault(pid, {})
                    entry[key_name] = text

        _load(prompts_path, "prompt")
        _load(original_path, "original")
        return result

