def _get_proxy_object(self, obj, ProxyKlass, proxy_klass_attribute):
        """ Returns the proxy object for an input object

        If the object is already the proxy object, return it.
        Otherwise set the appropriate proxy object to the proxy object's attribute
        """
        if obj is None:
            return None
        if isinstance(obj, ProxyKlass):
            return obj
        existing = getattr(obj, proxy_klass_attribute, None)
        if isinstance(existing, ProxyKlass):
            return existing
        proxy = ProxyKlass(obj)
        try:
            setattr(obj, proxy_klass_attribute, proxy)
        except Exception:
            pass
        return proxy

