def checkmagic(self):
        """
        Overridable.
        Check to see if the file object self.lib actually has a file
        we understand.
        """
        try:
            f = self.lib
            if not hasattr(f, "read"):
                return False
            pos = f.tell()
            header = f.read(8)
            f.seek(pos)
            if not header:
                return False
            magic = getattr(self, "_MAGIC", None)
            if magic is None:
                return True
            if isinstance(magic, (list, tuple, set)):
                return any(header.startswith(m) for m in magic)
            if isinstance(magic, (bytes, bytearray)):
                return header.startswith(magic)
            return False
        except Exception:
            return False

