def bot_yformatter(self, val, type=''):
        """custom formatter for FuncFormatter() and bottom panel"""
        import math

        # Determine formatting based on the optional type argument
        if type == 'pct':
            # Percentage format with one decimal place
            try:
                pct = float(val) * 100
                return f"{pct:.1f}%"
            except (TypeError, ValueError):
                return str(val)

        if type == 'time':
            # Assume val is seconds; format as HH:MM:SS
            try:
                total_seconds = int(round(float(val)))
                hours, remainder = divmod(total_seconds, 3600)
                minutes, seconds = divmod(remainder, 60)
                if hours:
                    return f"{hours:d}:{minutes:02d}:{seconds:02d}"
                else:
                    return f"{minutes:d}:{seconds:02d}"
            except (TypeError, ValueError):
                return str(val)

        # Default numeric formatting
        try:
            num = float(val)
        except (TypeError, ValueError):
            return str(val)

        # Integers are shown without decimal part
        if num.is_integer():
            return f"{int(num)}"

