def run(self, **run_params):
        """Run the simulation (or lookup the results in the cache)."""
        # Ensure a cache attribute exists
        if not hasattr(self, "_cache"):
            self._cache = {}
        # Create a hashable key from the run parameters
        try:
            key = tuple(sorted(run_params.items()))
        except TypeError:
            # Fallback for unhashable values: use repr
            key = tuple(sorted((k, repr(v)) for k, v in run_params.items()))
        # Return cached result if available
        if key in self._cache:
            return self._cache[key]
        # Compute the result using the class's simulation method
        if not hasattr(self, "_simulate"):
            raise NotImplementedError("Subclasses must implement a _simulate method.")
        result = self._simulate(**run_params)
        # Store and return the result
        self._cache[key] = result
        return result

