def compute(self, x, y):
        """
        Compute distance.

        Args:
            x:    Data point.
            y:    Data point.

        Returns:
            Distance.
        """
        import math
        # Handle scalar inputs
        if not hasattr(x, "__iter__") or isinstance(x, (str, bytes)):
            if not hasattr(y, "__iter__") or isinstance(y, (str, bytes)):
                return abs(x - y)
        # Handle iterable inputs
        xs = list(x)
        ys = list(y)
        if len(xs) != len(ys):
            raise ValueError("x and y must have the same length")
        return math.sqrt(sum((a - b) ** 2 for a, b in zip(xs, ys)))

