def cross(self, vector):
        """Return a Vector instance as the cross product of two vectors"""
        if len(self) != 3 or len(vector) != 3:
            raise ValueError("Cross product is defined for 3-dimensional vectors")
        a1, a2, a3 = self[0], self[1], self[2]
        b1, b2, b3 = vector[0], vector[1], vector[2]
        return self.__class__(a2 * b3 - a3 * b2,
                              a3 * b1 - a1 * b3,
                              a1 * b2 - a2 * b1)

