def extractValue(self, model, item):
        """
        Get the class name of the factory referenced by a port.

        @param model: Either a TabularDataModel or a ScrollableView, depending
        on what this column is part of.

        @param item: A port item instance (as defined by L{xmantissa.port}).

        @rtype: C{unicode}
        @return: The name of the class of the item to which this column's
        attribute refers.
        """
        # Determine the attribute name that holds the factory reference.
        # It is assumed that the column instance defines `self.attribute`
        # (or falls back to `self.name`) to specify which attribute of `item`
        # should be inspected.
        attr_name = getattr(self, "attribute", getattr(self, "name", None))
        if not attr_name:
            return u""
        # Retrieve the attribute from the item; if missing, return empty string.
        try:
            value = getattr(item, attr_name)
        except Exception:
            return u""
        # If the value is a class (factory) itself, use its name directly.
        if isinstance(value, type):
            class_name = value.__name__
        else:
            # Otherwise, use the class of the instance.
            class_name = value.__class__.__name__ if value is not None else ""
        return u"" if not class_name else class_name

