def sync(coro, timeout=None):
    """
    Schedule a coroutine to run on the global loop and return it's result.

    Args:
        coro (coroutine): The coroutine instance.

    Notes:
        This API is thread safe and should only be called by non-loop threads.
    """
    import asyncio
    loop = asyncio.get_event_loop()
    if loop.is_running():
        # Running loop (likely in another thread); submit coroutine thread‑safely.
        future = asyncio.run_coroutine_threadsafe(coro, loop)
        return future.result(timeout)
    # No running loop in this thread; create a temporary one.
    async def _run():
        return await coro
    if timeout is None:
        return asyncio.run(_run())
    else:
        return asyncio.run(asyncio.wait_for(_run(), timeout))

