def absolute_output_path(
            output_folder, components, component_key):
        """Return absolute output path of component.

        :param output_folder: The base output folder
        :type output_folder: str

        :param components: The list of components to look up
        :type components: list[ReportMetadata]

        :param component_key: The component key
        :type component_key: str

        :return: absolute output path
        :rtype: str

        .. versionadded:: 4.0
        """
        import os

        # Find the component with the matching key
        for comp in components:
            # Support both attribute and dict-like access
            key = getattr(comp, "key", None) if not isinstance(comp, dict) else comp.get("key")
            if key == component_key:
                # Determine the relative output path
                rel_path = (
                    getattr(comp, "output_path", None)
                    if not isinstance(comp, dict)
                    else comp.get("output_path")
                )
                if not rel_path:
                    # Fallback to a generic 'output' attribute or the key itself
                    rel_path = (
                        getattr(comp, "output", None)
                        if not isinstance(comp, dict)
                        else comp.get("output")
                    )
                if not rel_path:
                    raise ValueError(
                        f"Component '{component_key}' does not specify an output path."
                    )
                # Build and return the absolute path
                return os.path.abspath(os.path.join(output_folder, rel_path))

        raise ValueError(f"Component with key '{component_key}' not found.")

