def select_from_drop_down_by_locator(self, drop_down_locator, option_locator, params=None):
        """
        Select option from drop down widget using locator.

        :param drop_down_locator: locator tuple or WebElement instance
        :param option_locator: locator tuple or WebElement instance
        :param params: Dictionary containing dictionary of params
        :return: None
        """
        if params is None:
            params = {}
        timeout = params.get('timeout', 10)

        driver = getattr(self, 'driver', None)
        if driver is None:
            raise AttributeError("Instance has no attribute 'driver'")

        from selenium.webdriver.support.ui import WebDriverWait
        from selenium.webdriver.support import expected_conditions as EC

        def _resolve(locator):
            if isinstance(locator, tuple):
                return WebDriverWait(driver, timeout).until(EC.element_to_be_clickable(locator))
            else:
                # Assume it's already a WebElement; ensure it's interactable
                return WebDriverWait(driver, timeout).until(EC.element_to_be_clickable((lambda: locator, "")))

        # Click the drop‑down to reveal options
        drop_down_elem = _resolve(drop_down_locator)
        drop_down_elem.click()

        # Locate and click the desired option
        option_elem = _resolve(option_locator)
        option_elem.click()

