def as_list(func):
    """ A decorator used to return a JSON response of a list of model
        objects. It expects the decorated function to return a list
        of model instances. It then converts the instances to dicts
        and serializes them into a json response

        Examples:

            >>> @app.route('/api')
            ... @as_list
            ... def list_customers():
            ...     return Customer.all()

    """
    import json
    from functools import wraps

    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        if not isinstance(result, (list, tuple)):
            raise TypeError("as_list decorator expects the wrapped function to return a list or tuple")
        serialized = []
        for item in result:
            if hasattr(item, "to_dict") and callable(item.to_dict):
                serialized.append(item.to_dict())
            elif isinstance(item, dict):
                serialized.append(item)
            else:
                # Fallback: use __dict__ but filter out private attributes
                serialized.append({k: v for k, v in vars(item).items() if not k.startswith('_')})
        return json.dumps(serialized)
    return wrapper

