def stretch(image, mask=None):
    """Normalize an image to make the minimum zero and maximum one

    image - pixel data to be normalized
    mask  - optional mask of relevant pixels. None = don't mask

    returns the stretched image
    """
    import numpy as np

    img = np.asarray(image, dtype=float)

    if mask is not None:
        m = np.asarray(mask, dtype=bool)
        if m.shape != img.shape:
            raise ValueError("mask must have the same shape as image")
        if not np.any(m):
            return np.zeros_like(img, dtype=float)
        data = img[m]
    else:
        data = img.ravel()

    vmin = data.min()
    vmax = data.max()

    if vmax > vmin:
        stretched = (img - vmin) / (vmax - vmin)
    else:
        stretched = np.zeros_like(img, dtype=float)

    return stretched

