def res_to_url(resource, action):
    """Convert resource.action to (url, HTTP_METHOD)"""
    # Mapping of actions to HTTP method and whether they require an identifier
    _action_map = {
        "list": ("GET", False),
        "create": ("POST", False),
        "retrieve": ("GET", True),
        "update": ("PUT", True),
        "partial_update": ("PATCH", True),
        "destroy": ("DELETE", True),
    }

    if action not in _action_map:
        raise ValueError(f"Unsupported action: {action!r}")

    method, needs_id = _action_map[action]
    if needs_id:
        url = f"/{resource}/{{id}}/"
    else:
        url = f"/{resource}/"
    return url, method

