def locale_negotiator(request):
    """Locale negotiator base on the `Accept-Language` header"""
    header = request.headers.get('Accept-Language', '')
    if not header:
        return None
    locales = []
    for part in header.split(','):
        if ';' in part:
            lang, qpart = part.split(';', 1)
            lang = lang.strip()
            try:
                q = float(qpart.split('=')[1])
            except (IndexError, ValueError):
                q = 0.0
        else:
            lang = part.strip()
            q = 1.0
        if lang == '*':
            continue
        locales.append((q, len(locales), lang))
    if not locales:
        return None
    locales.sort(key=lambda x: (-x[0], x[1]))
    return locales[0][2]

