def learn_path(self, path):
        """Inserts `path` into correct global table.

        Since known paths to `Destination` has changes, we queue it for further
        processing.
        """
        # Ensure the global storage structures exist
        if not hasattr(self, "_global_paths"):
            self._global_paths = {}
        if not hasattr(self, "_processing_queue"):
            from collections import deque
            self._processing_queue = deque()

        # Determine destination key; support common path representations
        dest = None
        if isinstance(path, dict) and "destination" in path:
            dest = path["destination"]
        elif hasattr(path, "destination"):
            dest = getattr(path, "destination")
        elif isinstance(path, (list, tuple)) and len(path) >= 2:
            dest = path[0]

        # Insert into the appropriate global table if a destination can be resolved
        if dest is not None:
            # Store the most recent path for the destination
            self._global_paths[dest] = path
        else:
            # Fallback: store under a generic key to avoid loss of data
