def _gsa_total_force(force_vectors, vector_length):
    """Return a randomly weighted sum of the force vectors.

    args:
        force_vectors: A list of force vectors on solution i.

    returns:
        numpy.array; The total force on solution i.
    """
    import numpy as np

    if not force_vectors:
        return np.zeros(vector_length)

    weights = np.random.rand(len(force_vectors))
    total_weight = weights.sum()
    if total_weight == 0:
        weights = np.ones_like(weights) / len(weights)
    else:
        weights /= total_weight

    total_force = np.zeros(vector_length)
    for w, vec in zip(weights, force_vectors):
        total_force += w * np.asarray(vec, dtype=float)

    return total_force

