    type_part = parts[0].strip()
    if '/' not in type_part:
        raise ValueError(f"Invalid media type: '{type_part}'")
    maintype, subtype = (t.strip().lower() for t in type_part.split('/', 1))
    if not maintype or not subtype:
        raise ValueError(f"Invalid media type: '{type_part}'")
