        """
        X : ANTsImage | string | list of ANTsImage types | list of strings
            images to register to fixed image

        y : string | list of strings
            labels for images
        """
        import ants
        # Ensure X is iterable
        if isinstance(X, (list, tuple)):
            X_list = list(X)
        else:
            X_list = [X]

        # Convert each entry to ANTsImage
        processed_X = []
        for img in X_list:
            if isinstance(img, ants.ANTsImage):
                processed_X.append(img)
            elif isinstance(img, str):
                processed_X.append(ants.image_read(img))
            else:
                raise TypeError(
                    f"Unsupported type for X element: {type(img)}. "
                    "Expected ANTsImage or file path string."
                )
        self.X_ = processed_X

        # Process optional labels y
        if y is not None:
            if isinstance(y, (list, tuple)):
                y_list = list(y)
            else:
                y_list = [y]

            if len(y_list) != len(processed_X):
                raise ValueError(
