def generate_short_url(self):
        """
        Returns a new short URL generated using bit.ly if credentials for the
        service have been specified.
        """
        import json, requests

        # Expect the instance to have `url` (the long URL) and optional Bitly credentials.
        long_url = getattr(self, "url", None)
        if not long_url:
            raise ValueError("Instance must have a `url` attribute to shorten.")

        # Bitly token can be stored as `bitly_token` or as a dict `bitly_credentials`
        token = getattr(self, "bitly_token", None)
        if not token:
            creds = getattr(self, "bitly_credentials", {})
            token = creds.get("access_token") or creds.get("token")
        if not token:
            # No credentials – nothing to do.
            return None

        api_url = "https://api-ssl.bitly.com/v4/shorten"
        headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        }
        payload = {"long_url": long_url}
        try:
            response = requests.post(api_url, headers=headers, data=json.dumps(payload), timeout=10)
            response.raise_for_status()
            data = response.json()
            return data.get("link")
        except requests.RequestException as exc:
            # Propagate a clear error for callers.
            raise RuntimeError(f"Failed to generate Bitly short URL: {exc}") from exc

