def _publish_match(self, publish, names=False, name_only=False):
        """
        Check if publish name matches list of names or regex patterns
        """
        import re
        # If no name restrictions provided, consider it a match
        if not names:
            return True

        # Ensure names is iterable
        try:
            iterator = iter(names)
        except TypeError:
            # Single name/pattern provided
            iterator = [names]

        for pattern in iterator:
            if name_only:
                if publish == pattern:
                    return True
            else:
                # If pattern is a compiled regex, use its search method
                if isinstance(pattern, re.Pattern):
                    if pattern.search(publish):
                        return True
                else:
                    # Treat pattern as a regex string
                    if re.search(pattern, publish):
                        return True
        return False

