                           prettyname, device):
        """
        Calulates the difference between to point, and scales is to per second.
        """
        if time_delta:
            try:
                rate = (float(value_delta) / float(time_delta)) * float(multiplier)
            except (TypeError, ValueError, ZeroDivisionError):
                rate = 0.0
        else:
            rate = 0.0
        return {
            "path": path,
            "value_per_sec": rate,
            "prettyname": prettyname,
            "device": device,
        }

