def make_field(self, field_name, field_body):
        """Fill content into nodes.

        :param string field_name: Field name of the field
        :param field_name: Field body if the field
        :type field_name: str or instance of docutils.nodes
        :return: field instance filled with given name and body
        :rtype: nodes.field

        """
        from docutils import nodes

        # Prepare field name node
        if isinstance(field_name, nodes.field_name):
            name_node = field_name
        else:
            # Accept raw string or any node that can be converted to Text
            if isinstance(field_name, str):
                name_node = nodes.field_name('', nodes.Text(field_name))
            else:
                # Assume it's a node that can be placed directly
                name_node = nodes.field_name('', field_name)

        # Prepare field body node
        if isinstance(field_body, nodes.field_body):
            body_node = field_body
        else:
            if isinstance(field_body, str):
                para = nodes.paragraph('', nodes.Text(field_body))
                body_node = nodes.field_body('', para)
            elif isinstance(field_body, list):
                # List of nodes assumed to be ready for field_body
                body_node = nodes.field_body('', *field_body)
            else:
                # Single node (e.g., paragraph, literal_block, etc.)
                body_node = nodes.field_body('', field_body)

        return nodes.field('', name_node, body_node)

