def _reset(cls):
        """If we have forked since the watch dictionaries were initialized, all
        that has is garbage, so clear it."""
        import os
        current_pid = os.getpid()
        if getattr(cls, "_pid", None) != current_pid:
            # Clear all class‑level dict attributes (watch dictionaries)
            for name, value in vars(cls).items():
                if isinstance(value, dict):
                    try:
                        value.clear()
                    except Exception:
                        # If the dict is read‑only or cannot be cleared, replace it
                        setattr(cls, name, {})
            cls._pid = current_pid

