def load_plugins(self, ):
        """Loads all found plugins

        :returns: None
        :rtype: None
        :raises: None
        """
        import importlib
        import os
        import pkgutil
        from types import ModuleType

        # Determine where to look for plugins
        plugin_path = getattr(self, "plugins_path", None)
        plugin_package = getattr(self, "plugins_package", None)

        # Prepare a container for loaded plugin modules
        if not hasattr(self, "plugins"):
            self.plugins = []

        # Helper to load a module given its name and optional package
        def _load_module(module_name: str, package: str | None = None) -> ModuleType | None:
            try:
                full_name = f"{package}.{module_name}" if package else module_name
                return importlib.import_module(full_name)
            except Exception:
                return None

        # Load from a filesystem path
        if plugin_path and os.path.isdir(plugin_path):
            for finder, name, ispkg in pkgutil.iter_modules([plugin_path]):
                if ispkg:
                    continue
                mod = _load_module(name)
                if mod:
                    self.plugins.append(mod)

        # Load from a package name
        elif plugin_package:
            try:
                pkg = importlib.import_module(plugin_package)
            except Exception:
                pkg = None
            if pkg and hasattr(pkg, "__path__"):
                for finder, name, ispkg in pkgutil.iter_modules(pkg.__path__):
                    if ispkg:
                        continue
                    mod = _load_module(name, plugin_package)
                    if mod:
                        self.plugins.append(mod)

