def setup_logger(logging_level, logging_format):
    """Setup default logging for ray."""
    import logging

    # Resolve logging level
    if isinstance(logging_level, str):
        level = getattr(logging, logging_level.upper(), None)
        if level is None:
            raise ValueError(f"Invalid logging level: {logging_level}")
    else:
        level = logging_level

    # Configure root logger if it has no handlers yet
    root_logger = logging.getLogger()
    if not root_logger.handlers:
        logging.basicConfig(level=level, format=logging_format)
    else:
        root_logger.setLevel(level)
        formatter = logging.Formatter(logging_format)
        for handler in root_logger.handlers:
            handler.setFormatter(formatter)

    # Ensure the 'ray' logger follows the same configuration
    ray_logger = logging.getLogger("ray")
    ray_logger.setLevel(level)
    return ray_logger

