def insertBPoint(self, index, type=None, anchor=None, bcpIn=None, bcpOut=None, bPoint=None):
        """
        Insert a bPoint at index in the contour.
        """
        # Ensure the contour has a list to store points
        if not hasattr(self, 'points') or self.points is None:
            self.points = []
        # Validate index
        if index < 0 or index > len(self.points):
            raise IndexError(f'Index {index} out of bounds for contour of size {len(self.points)}')
        # Use provided bPoint or create a new one
        if bPoint is None:
            bPoint = {}
        # Assign optional attributes if given
        if type is not None:
            bPoint['type'] = type
        if anchor is not None:
            bPoint['anchor'] = anchor
        if bcpIn is not None:
            bPoint['bcpIn'] = bcpIn
        if bcpOut is not None:
            bPoint['bcpOut'] = bcpOut
        # Insert the point at the specified index
        self.points.insert(index, bPoint)
        return bPoint

