        Prints all states state and their steady state probabilities.
        Not recommended for large state spaces.
        """
        # Retrieve states and steady‑state probabilities, handling common attribute names
        states = getattr(self, "states", getattr(self, "_states", []))
        pi = getattr(self, "pi", getattr(self, "_pi", None))

        # If probabilities are stored as a dict, use its items directly
        if isinstance(pi, dict):
            for state, prob in pi.items():
                print(f"{state}: {prob}")
            return

        # If probabilities are a list/array, pair them with the states list
        if pi is not None:
            try:
                iterator = zip(states, pi)
            except TypeError:
                iterator = []
            for state, prob in iterator:
                print(f"{state}: {prob}")
            return

        # Fallback: try to compute steady‑state if a method exists
        if hasattr(self, "steady_state"):
            try:
                pi = self.steady_state()
                for state, prob in zip(states, pi):
                    print(f"{state}: {prob}")
            except Exception:
                pass
        # Nothing to print if no data available
        return

