def send(self, message):
        """Sends a RTMMessage
        Should be called after starting the loop

        Args:
            message(RTMMessage): the sending message

        Raises:
            WebSocketConnectionClosedException: if the loop is closed
        """
        if not getattr(self, "_ws", None):
            raise WebSocketConnectionClosedException()
        try:
            # Prefer a dedicated serialization method if available
            if hasattr(message, "to_dict"):
                data = message.to_dict()
            elif hasattr(message, "__dict__"):
                data = message.__dict__
            else:
                data = dict(message)
        except Exception as exc:
            raise TypeError(f"Unable to serialize message: {exc}") from exc

        try:
            self._ws.send(json.dumps(data))
        except WebSocketConnectionClosedException:
            raise
        except Exception as exc:
            # Re‑raise as connection‑closed to keep the public API consistent
            raise WebSocketConnectionClosedException(str(exc)) from exc

