def get_json_encoders_for_type(self, type_to_encode: type) -> Optional[Iterable[JSONEncoder]]:
        """
        Gets the registered JSON encoder for the given type.
        :param type_to_encode: the type of object that is to be encoded
        :return: the encoder for the given object else `None` if unknown
        """
        # Assume self._json_encoders is a dict mapping a type to an iterable of JSONEncoder instances
        encoders = getattr(self, "_json_encoders", {})
        # Direct match
        if type_to_encode in encoders:
            return encoders[type_to_encode]
        # Look for a registered encoder for a base class / abstract type
        for registered_type, registered_encoders in encoders.items():
            try:
                if issubclass(type_to_encode, registered_type):
