def fprop(self, x):
    """
    Performs a forward pass through the DkNN on a TF tensor by wrapping
    the fprop_np method.
    """
    import tensorflow as tf
    if tf.executing_eagerly():
        # Eager mode: convert to NumPy, call fprop_np, convert back
        np_input = x.numpy() if hasattr(x, "numpy") else x
        np_output = self.fprop_np(np_input)
        return tf.convert_to_tensor(np_output, dtype=x.dtype)
    else:
        # Graph mode: wrap fprop_np with tf.py_function
        def _wrapped(np_input):
            return self.fprop_np(np_input)

        output = tf.py_function(_wrapped, [x], Tout=x.dtype)
        # Preserve static shape information if possible
        try:
            output.set_shape(x.shape)
        except Exception:
            pass
        return output

