def AsCGI(nsdict={}, typesmodule=None, rpc=False, modules=None):
    """Dispatch within a CGI script.
    """
    import sys, os, json, cgi, importlib
    # Prepare namespace
    ns = dict(nsdict) if nsdict else {}
    if modules:
        for mod_name in modules:
            try:
                mod = importlib.import_module(mod_name)
                ns.update(vars(mod))
            except Exception:
                pass

    # Parse CGI input
    form = cgi.FieldStorage()
    # Helper to extract values
    def get_value(key):
        if key not in form:
            return None
        val = form.getvalue(key)
        return val

    # RPC mode
    if rpc:
        method_name = get_value('method')
        if not method_name:
            print('Content-Type: text/plain\n')
            print('Missing "method" parameter')

