        """Add to recent file list"""
        # Ensure the recent files list exists
        if not hasattr(self, "recent_files") or self.recent_files is None:
            self.recent_files = []

        # Remove the file if it already exists to avoid duplicates
        try:
            self.recent_files.remove(fname)
        except ValueError:
            pass

        # Insert the new file at the beginning (most recent)
        self.recent_files.insert(0, fname)

