def grok_ttl(secret):
    """Parses the TTL information"""
    import re

    if isinstance(secret, (int, float)):
        return int(secret)

    if isinstance(secret, dict):
        if 'ttl' in secret:
            return grok_ttl(secret['ttl'])
        raise ValueError("Dictionary does not contain 'ttl' key")

    if not isinstance(secret, str):
        raise TypeError("Unsupported type for TTL parsing")

    secret = secret.strip().lower()

    # Direct integer string
    if secret.isdigit():
        return int(secret)

    # Match patterns like "ttl=3600", "expires in 2h", "2h30m", "2 h 30 m"
    m = re.search(r'(\d+)\s*([smhdw])', secret)
    if m:
        total = 0
        for num, unit in re.findall(r'(\d+)\s*([smhdw])', secret):
            num = int(num)
            if unit == 's':
                total += num
            elif unit == 'm':
                total += num * 60
            elif unit == 'h':
                total += num * 3600
            elif unit == 'd':
                total += num * 86400
            elif unit == 'w':
                total += num * 604800
        return total

    # Fallback: extract first integer found
    m = re.search(r'\d+', secret)

