def _port_op(op_name, port, protocol="TCP"):
    """Open or close a service network port"""
    import socket
    import threading

    if not hasattr(_port_op, "_lock"):
        _port_op._lock = threading.Lock()
    if not hasattr(_port_op, "_sockets"):
        _port_op._sockets = {}

    op = op_name.lower()
    if op not in ("open", "close"):
        raise ValueError(f"Unsupported operation '{op_name}'. Use 'open' or 'close'.")

    with _port_op._lock:
        if op == "open":
            if port in _port_op._sockets:
                raise OSError(f"Port {port} is already opened.")
            family = socket.AF_INET
            if protocol.upper() == "TCP":
                typ = socket.SOCK_STREAM

