def _get_converter(self, converter_str):
        """find converter function reference by name

        find converter by name, converter name follows this convention:

            Class.method

        or:

            method

        The first type of converter class/function must be available in
        current module.
        The second type of converter must be available in `__builtin__`
        (or `builtins` in python3) module.

        :param converter_str: string representation of the converter func
        :return: function reference
        """
        parts = converter_str.split('.')
        if len(parts) == 2:
            class_name, func_name = parts
            try:
                cls = globals()[class_name]
            except KeyError as e:
                raise ImportError(f"Converter class '{class_name}' not found") from e
            try:
                return getattr(cls, func_name)
            except AttributeError as e:
                raise ImportError(f"Converter '{converter_str}' not found in class '{class_name}'") from e
        elif len(parts) == 1:
            import builtins
            try:
                return getattr(builtins, converter_str)
            except AttributeError as e:
                raise ImportError(f"Builtin converter '{converter_str}' not found") from e
        else:
            raise ValueError(f"Invalid converter string: '{converter_str}'")

