def add_rule(self, rule):
        """Supported rules: `a -> b` and `a => b` (terminal rule)."""
        if not isinstance(rule, str):
            raise TypeError("rule must be a string")
        rule = rule.strip()
        if "=>" in rule:
            parts = rule.split("=>", 1)
            is_terminal = True
        elif "->" in rule:
            parts = rule.split("->", 1)
            is_terminal = False
        else:
            raise ValueError("Unsupported rule format; expected 'a -> b' or 'a => b'")
        lhs, rhs = (p.strip() for p in parts)
        if not lhs or not rhs:
            raise ValueError("Both left-hand side and right-hand side must be non‑empty")
        if is_terminal:
            if not hasattr(self, "terminals"):
                self.terminals = {}
            self.terminals[lhs] = rhs
        else:
            if not hasattr(self, "rules"):
                self.rules = {}
