    """Calls `delete()` on all members of `obj` that are recognized as
    instances of `pg` objects."""
    import inspect
    import pg

    def _is_pg_instance(value):
        try:
            return isinstance(value, pg.BaseObject)  # type: ignore[attr-defined]
        except Exception:
            return False

    for name, member in inspect.getmembers(obj):
        if _is_pg_instance(member) and hasattr(member, "delete"):
            try:
                member.delete()
            except Exception:
                pass

