def do_callback(self, pkt):
        """Add the callback to the event loop, we use call soon because we just
        want it to be called at some point, but don't care when particularly.
        """
        import asyncio
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = asyncio.get_event_loop()
        cb = getattr(self, "callback", None) or getattr(self, "_callback", None)
        if cb is None:
            return
        if asyncio.iscoroutinefunction(cb):
            loop.create_task(cb(pkt))
        else:
            loop.call_soon(cb, pkt)

