def ks_pvalue(fg_pos, bg_pos=None):
    """
    Computes the Kolmogorov-Smirnov p-value of position distribution.

    Parameters
    ----------
    fg_pos : array_like
        The list of values for the positive set.

    bg_pos : array_like, optional
        The list of values for the negative set.

    Returns
    -------
    p : float
        KS p-value.
    """
    import numpy as np
    from scipy import stats

    fg = np.asarray(fg_pos, dtype=float).ravel()
    if fg.size == 0:
        return float('nan')

    if bg_pos is None:
        # One-sample KS test against a uniform distribution on the range of fg
        lo, hi = fg.min(), fg.max()
        if lo == hi:
            return 1.0  # all values identical, trivially uniform
        scaled = (fg - lo) / (hi - lo)
        _, p = stats.kstest(scaled, 'uniform')
        return float(p)
    else:
        bg = np.asarray(bg_pos, dtype=float).ravel()
        if bg.size == 0:
            return float('nan')
        _, p = stats.ks_2samp(fg, bg, alternative='two-sided', mode='auto')
        return float(p)

