def update_gl_state(self, *args, **kwargs):
        """Modify the set of GL state parameters to use when drawing

        Parameters
        ----------
        *args : tuple
            Arguments.
        **kwargs : dict
            Keyword argments.
        """
        if not hasattr(self, '_gl_state'):
            self._gl_state = {}
        reset = kwargs.pop('reset', False)
        if reset:
            self._gl_state.clear()
        for arg in args:
            if isinstance(arg, dict):
                self._gl_state.update(arg)
            else:
                try:
                    for k, v in arg:
