        popen_args = {"args": command, "shell": True}
    # Ensure the provided tempFile is a file-like object with a writeable buffer
    # If a path string is given, open it for writing in binary mode
    close_file = False
    if isinstance(tempFile, str):
        tempFile = open(tempFile, "wb")
        close_file = True
    try:
        proc = subprocess.Popen(
            **popen_args,
            stdout=tempFile,
            stderr=subprocess.STDOUT,
        )
        proc.wait()
        return proc.returncode
    finally:
        if close_file:
            tempFile.close()

