def check_between(v_min, v_max, **params):
    """Checks parameters are in a specified range

    Parameters
    ----------

    v_min : float, minimum allowed value (inclusive)

    v_max : float, maximum allowed value (inclusive)

    params : object
        Named arguments, parameters to be checked

    Raises
    ------
    ValueError : unacceptable choice of parameters
    """
    for name, value in params.items():
        try:
            if not (v_min <= value <= v_max):
                raise ValueError
        except TypeError:
            raise ValueError(f"Parameter '{name}' has non-numeric value {value!r}")
        else:
            if not (v_min <= value <= v_max):
                raise ValueError(f"Parameter '{name}'={value} not in range [{v_min}, {v_max}]")

