        raise ValueError("hist must be a 1‑dimensional array of bin counts")
    if min_val >= max_val:
        raise ValueError("bin_range must have min < max")
    if np.any(hist < 0):
        raise ValueError("hist counts must be non‑negative")

    # Compute bin edges
    edges = np.linspace(min_val, max_val, len(hist) + 1)

    # Generate samples uniformly within each bin
    samples = [
        np.random.uniform(edges[i], edges[i + 1], size=count)
        for i, count in enumerate(hist) if count > 0
    ]

    if samples:
        return np.concatenate(samples)
    else:
        # No data to generate; return empty array of appropriate dtype
        return np.array([], dtype=float)

