def observe(self, event_name, func):
        """
        event_name := {'created', 'modified', 'deleted'}, list, tuple

        Attaches a function to run to a particular event. The function must be
        unique to be removed cleanly. Alternatively, event_name can be an list/
        tuple if any of the string possibilities to be added on multiple events
        """
        # Initialize observer storage if not present
        if not hasattr(self, "_observers"):
            self._observers = {e: [] for e in ("created", "modified", "deleted")}

        # Determine iterable of event names
        if isinstance(event_name, (list, tuple, set)):
            events = event_name
        else:
            events = (event_name,)

        # Validate and attach the function
        for ev in events:
            if ev not in self._observers:
                raise ValueError(f"Unsupported event name: {ev!r}")
            if func not in self._observers[ev]:
                self._observers[ev].append(func)

