        """Retrieves the number of milliseconds during which the virtual machine
           has used the CPU. This value includes the time used by the guest
           operating system and the time used by virtualization code for tasks for this
           virtual machine. You can combine this value with the elapsed time
           (VMGuestLib_GetElapsedMs) to estimate the effective virtual machine
           CPU speed. This value is a subset of elapsedMs."""
        # Attempt to retrieve the CPU used time from known attribute locations.
        # Preference order: explicit attribute, then dictionary entry, then fallback to 0.
        if hasattr(self, "_cpu_used_ms"):
            return int(self._cpu_used_ms)
        if hasattr(self, "properties") and isinstance(self.properties, dict):
            val = self.properties.get("cpuUsedMs") or self.properties.get("cpu_used_ms")
            if val is not None:
                return int(val)
        # If the object provides a generic getter method, try using it.
        if hasattr(self, "get_property"):
            try:
                val = self.get_property("cpuUsedMs")
                if val is not None:
                    return int(val)
            except Exception:
                pass
        # Default to 0 if no information is available.
