        """Apply the context to the current python session.

        Note that this updates os.environ and possibly sys.path, if
        `parent_environ` is not provided.

        Args:
            parent_environ: Environment to interpret the context within,
                defaults to os.environ if None.
        """
        # Determine the environment mapping to modify
        if parent_environ is None:
            env = os.environ
        else:
            # Ensure the provided mapping supports item assignment
            if not hasattr(parent_environ, "__setitem__"):
                raise TypeError("parent_environ must be a mutable mapping")
            env = parent_environ

        # Apply stored environment variables, if any
