def _center(code, segment_dict):
    """Starting with `code`, follow segments from target to center."""
    visited = set()
    while True:
        if code in visited:
            break
        visited.add(code)
        seg = segment_dict.get(code)
        if not isinstance(seg, dict):
            break
        target = seg.get('target')
        if not target or target == code:
            break
        code = target
    return code

