def _format_zinc_arguments(settings, distribution):
    """Extracts and formats the zinc arguments given in the jvm platform settings.

    This is responsible for the symbol substitution which replaces $JAVA_HOME with the path to an
    appropriate jvm distribution.

    :param settings: The jvm platform settings from which to extract the arguments.
    :type settings: :class:`JvmPlatformSettings`
    """
    # Retrieve zinc arguments from settings (support dict-like or attribute access)
    try:
        raw_args = settings.zinc_args
    except Exception:
        raw_args = getattr(settings, "zinc_args", None)
    if raw_args is None:
        # fallback for dict‑like objects
        raw_args = settings.get("zinc_args", []) if hasattr(settings, "get") else []
    # Ensure we have an iterable list
    if not isinstance(raw_args, (list, tuple)):
        raw_args = [raw_args]

    # Determine the Java home path from the distribution argument
    java_home = None
    if distribution is not None:
        if isinstance(distribution, str):
            java_home = distribution
        else:
            java_home = getattr(distribution, "java_home", None)

    # Perform substitution
    formatted = []
    for arg in raw_args:
        if isinstance(arg, str) and java_home:
            formatted.append(arg.replace("$JAVA_HOME", java_home))
        else:
            formatted.append(arg)
    return formatted

