def from_file(cls, filename):
        """
        Reads configuration from given path to a file in local file system and
        returns parsed version of it.

        :param filename: Path to the YAML file in local file system where the
                         configuration will be read from.
        :type filename: str

        :return: Configuration instance parsed from given configuration file.
        :rtype: Configuration
        """
        import os
        import yaml

        if not isinstance(filename, (str, bytes, os.PathLike)):
            raise TypeError("filename must be a path string or PathLike object")
        with open(filename, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)

        # Prefer a dedicated from_dict constructor if available
        if hasattr(cls, "from_dict") and callable(getattr(cls, "from_dict")):
            return cls.from_dict(data)

        # Fallback to normal instantiation
        if isinstance(data, dict):
            try:
                return cls(**data)
            except TypeError:
                return cls(data)
        return cls(data)

