def eatfd(self, fd):
        """
        Consume all the bytes from a file like object.

        Example:

            hset = HashSet()
            hset.eatfd(fd)

        """
        import os
        total = 0
        # If an integer file descriptor is passed, use os.read
        if isinstance(fd, int):
            while True:
                try:
                    chunk = os.read(fd, 8192)
                except OSError:
                    break
                if not chunk:
                    break
                total += len(chunk)
