def shutdown(self):
        """Send SIGABRT to child processes to instruct them to stop"""
        import os
        import signal

        # Retrieve the container of child processes; common attribute names are tried.
        children = getattr(self, "children", None) or getattr(self, "_children", None)
        if not children:
            return

        # Ensure we iterate over a static copy in case the collection is modified during shutdown.
        for child in list(children):
            try:
                pid = getattr(child, "pid", None)
                if pid:
                    os.kill(pid, signal.SIGABRT)
            except Exception:
                # Silently ignore errors such as the process already having exited.
                pass

