def error_wrapper(fn, error_class):  # type: (Callable or None, Exception) -> ...
    """Wraps function fn in a try catch block that re-raises error_class.

    Args:
        fn (function): function to wrapped
        error_class (Exception): Error class to be re-raised

    Returns:
        (object): fn wrapped in a try catch.
    """
    if fn is None:
        return None

    def _wrapped(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            # If error_class is an exception type, instantiate it with the original exception
            if isinstance(error_class, type) and issubclass(error_class, BaseException):
                raise error_class(e) from e
            # Otherwise, re‑raise the provided exception object
            raise error_class

    return _wrapped

