def _future_done(self, future):
        """ Will be called when the coroutine is done """
        if future.cancelled():
            # Propagate cancellation to the outer future if not already cancelled
            try:
                self._future.cancel()
            except Exception:
                pass
            return

        exc = future.exception()
        if exc is not None:
            # Propagate exception to the outer future
            if not self._future.done():
                self._future.set_exception(exc)
        else:
            # Propagate result to the outer future
            if not self._future.done():
                self._future.set_result(future.result())

