def merge(args):
    """
    %prog merge bedfiles > newbedfile

    Concatenate bed files together. Performing seqid and name changes to avoid
    conflicts in the new bed file.
    """
    import sys
    for idx, fname in enumerate(args):
        try:
            with open(fname, 'r') as fh:
                for line in fh:
                    if not line.strip() or line.startswith('#'):
                        continue
                    parts = line.rstrip('\n').split('\t')
                    if len(parts) < 3:
                        continue
                    # modify seqid (chrom)
                    parts[0] = f"{idx}_{parts[0]}"
                    # modify name if present
                    if len(parts) >= 4:
                        parts[3] = f"{idx}_{parts[3]}"
                    sys.stdout.write('\t'.join(parts) + '\n')
        except Exception as e:
            sys.stderr.write(f"Error processing {fname}: {e}\n")

