def uniprot_reviewed_checker(uniprot_id):
    """Check if a single UniProt ID is reviewed or not.

    Args:
        uniprot_id:

    Returns:
        bool: If the entry is reviewed

    """
    import json, urllib.request, urllib.error

    def _fetch_json(url):
        req = urllib.request.Request(url, headers={"Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                raise urllib.error.HTTPError(url, resp.status, resp.reason, resp.headers, None)
            return json.load(resp)

    url = f"https://rest.uniprot.org/uniprotkb/{uniprot_id}.json"
    try:
        data = _fetch_json(url)
    except urllib.error.HTTPError as e:
        if e.code == 404:
            raise ValueError(f"UniProt ID '{uniprot_id}' not found") from None
        raise RuntimeError(f"Error fetching UniProt entry: {e}") from None
    except Exception as e:
        raise RuntimeError(f"Error fetching UniProt entry: {e}") from None

    entry_type = data.get("entryType") or data.get("entryType", "")
    return str(entry_type).strip().lower() == "reviewed"

