    except Exception as e:
        raise ValueError(f"Operation '{operation_name}' not found in graph") from e

    dim_names = set()

    # Helper to extract dimension names from a TensorFlow tensor that may be an MTF tensor.
    def _extract_from_tensor(t):
        # MTF tensors have a .shape attribute with .dims list of Dimension objects.
        shape = getattr(t, "shape", None)
        if shape is None:
