        dims = getattr(shape, "dims", None)
        if not dims:
            return
        for d in dims:
            name = getattr(d, "name", None)
            if isinstance(name, str):
                dim_names.add(name)

    # Examine both inputs and outputs of the operation.
    for tensor in getattr(op, "inputs", []):
        _extract_from_tensor(tensor)
    for tensor in getattr(op, "outputs", []):
        _extract_from_tensor(tensor)

    return dim_names

