    global _INSTALLED_FILES
    if '_INSTALLED_FILES' not in globals():
        _INSTALLED_FILES = []
    def _add(t):
        path = str(t)
        if path not in _INSTALLED_FILES:
            _INSTALLED_FILES.append(path)
