def shutdown(self):
        """
        Close all connections.  ``Session`` instances should not be used
        for any purpose after being shutdown.
        """
        if getattr(self, "_closed", False):
            return
        self._closed = True
        errors = []
        for conn in getattr(self, "_connections", []):
            try:
                conn.close()
            except Exception as exc:
                errors.append(exc)
        if errors:
            raise RuntimeError("Error(s) occurred while shutting down connections") from errors[0]

