def to_drake_step(inputs, output):
    """
    Args:
        inputs: collection of input Steps
        output: output Step

    Returns: a string of the drake step for the given inputs and output
    """
    # Extract names from input steps, handling various possible attribute conventions
    def _get_name(step):
        for attr in ("name", "label", "id"):
            if hasattr(step, attr):
                return getattr(step, attr)
        # Fallback to string representation
        return str(step)

    input_names = [_get_name(s) for s in inputs] if inputs is not None else []
    output_name = _get_name(output)

    # Build the Drake step string
    if input_names:
        return f"{output_name} = {output_name}({', '.join(input_names)})"
    else:
        return f"{output_name} = {output_name}()"

