def reset_database(self):
        """
        Re-create an empty database.

        """
        import os
        import sqlite3

        # Close existing connection if open
        conn = getattr(self, "conn", None)
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
            self.conn = None

        # Remove the database file if it exists
        db_path = getattr(self, "db_path", None)
        if db_path and os.path.isfile(db_path):
            try:
                os.remove(db_path)
            except OSError:
                pass

        # Re‑create a new empty database
        if db_path:
            self.conn = sqlite3.connect(db_path)
        else:
            # Fallback: create an in‑memory database
            self.conn = sqlite3.connect(":memory:")

        # If the class defines a schema‑initialisation helper, invoke it
        init_method = getattr(self, "_initialize_schema", None)
        if callable(init_method):
            init_method()

