def DFS(G):
    """
    Algorithm for depth-first searching the vertices of a graph.
    """
    visited = set()
    order = []

    def _dfs(v):
        visited.add(v)
        order.append(v)
        for w in G.get(v, []):
            if w not in visited:
                _dfs(w)

    for vertex in G:
        if vertex not in visited:
            _dfs(vertex)

    return order

