        """
        This allows the client to change the parameters for an event, in the case that there is a desire for slightly different behavior, such as reasigning keys.

        handler - the handler object that the desired changes are made to.

        kwargs - the variable number of keyword arguments for the parameters that must match the properties of the corresponding event.
            """
        # Determine where to store the parameters: prefer a dict attribute named
        # ``params`` or ``event_params`` if present; otherwise fall back to setting
        # attributes directly on the handler.
        param_container = None
        for attr_name in ("params", "event_params"):
            if hasattr(handler, attr_name):
                container = getattr(handler, attr_name)
                if isinstance(container, dict):
                    param_container = container
                    break

        if param_container is not None:
            # Update the dictionary, ensuring only existing keys are modified.
            for key, value in kwargs.items():
                if key in param_container:
                    param_container[key] = value
                else:
                    raise AttributeError(
