def reload_module(self, module_name):
        """Reloads the specified module without changing its ordering.

        1. Calls stop(reloading=True) on the module
        2. Reloads the Module object into .loaded_modules
        3. Calls start(reloading=True) on the new object

        If called with a module name that is not currently loaded, it will load it.

        Returns True if the module was successfully reloaded, otherwise False.
        """
        try:
            import importlib
            if hasattr(self, "loaded_modules") and module_name in self.loaded_modules:
                old_mod = self.loaded_modules[module_name]
                if hasattr(old_mod, "stop"):
                    old_mod.stop(reloading=True)
                new_mod = importlib.reload(old_mod)
            else:
                new_mod = importlib.import_module(module_name)
            self.loaded_modules[module_name] = new_mod
            if hasattr(new_mod, "start"):
                new_mod.start(reloading=True)
            return True
        except Exception:
            return False

