        """
        Returns the status of the sandbox mode.

        Possible values are:
        - on
        - off
        - unknown
        - not installed
        """
        import subprocess, shutil

        def _run_cmd(cmd):
            try:
                out = subprocess.check_output(cmd, stderr=subprocess.STDOUT, shell=True, text=True)
                return out.strip().lower()
            except subprocess.CalledProcessError:
                return ""

        # Determine if sandbox tool is available
        sandbox_cmd = "sandboxctl"
        if not shutil.which(sandbox_cmd):
            return "not installed"

        # Build command based on optional vm_name
        if vm_name:
            cmd = f"{sandbox_cmd} status {vm_name}"
        else:
            cmd = f"{sandbox_cmd} status"

        output = _run_cmd(cmd)

        if not output:
            return "unknown"

