def createSegments(self, cells):
    """
    Create a segment on each of the specified cells.

    @param cells (numpy array)
    """
    import numpy as np
    # Ensure the instance has a container for segments
    if not hasattr(self, 'segments') or self.segments is None:
        self.segments = {}
    # Normalize input to a 2‑D array of coordinates
    arr = np.atleast_2d(np.asarray(cells))
    created = []
    for coord in arr:
        # Convert coordinate to a hashable tuple of ints
        key = tuple(int(v) for v in coord)
        # Create a simple segment representation; can be replaced by a richer object
        segment = {'cell': key}
        self.segments[key] = segment
        created.append(segment)
    return

