def szipper(inbox, s=None):
    """
    Zips inputs from inbox with indicies in "s". By default zips the whole 
    inbox (all indices).

    Arguments:

      - s(sequence) [default: ``None``]    

    """
    seq = list(inbox)
    if s is None:
        return list(enumerate(seq))
    result = []
    n = len(seq)
    for i in s:
        if isinstance(i, int) and -n <= i < n:
            result.append((i, seq[i]))
    return result

