def frameify(self, state, data):
        """Split data into a sequence of frames."""
        if state is None:
            state = {}
        buffer = state.get('buffer', b'')
        if isinstance(data, str):
            data = data.encode()
        buffer += data
        frames = []
        while True:
            sep_index = buffer.find(b'\n')
            if sep_index == -1:
                break
            frames.append(buffer[:sep_index])
            buffer = buffer[sep_index + 1 :]
        state['buffer'] = buffer
        return frames

