        Parse the metrics.tsv file from RNA-SeQC
        """
        metrics = {}
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) < 2:
                continue
            key, val = parts[0].strip(), parts[1].strip()
