def load_from_dict(self, data: dict, overwrite: bool=True):
        """
        Loads key/values from dicts or list into the ConfigKey.
        :param data: The data object to load.
                        This can be a dict, or a list of key/value tuples.
        :param overwrite: Should the ConfigKey overwrite data already in it?
        """
        if isinstance(data, dict):
            items = data.items()
        elif isinstance(data, (list, tuple)):
            items = data
        else:
            raise TypeError("data must be a dict or a list/tuple of key/value pairs")
        for key, value in items:
            if isinstance(value, dict):
                if key in self._data and isinstance(self._data[key], self.__class__):
                    self._data[key].load_from_dict(value, overwrite)
                else:
                    sub = self.__class__()
                    sub.load_from_dict(value, overwrite)
                    self._data[key] = sub
            else:
                if overwrite or key not in self._data:
                    self._data[key] = value
        return self

