    """
    Assigns a permissions dict to the given model, much like Django
    does with its dashboard app list.

    Used within the change list for pages, to implement permission
    checks for the navigation tree.
    """
    # Ensure token is iterable of permission names
    if token is None:
        perms = {}
    elif isinstance(token, (list, tuple, set)):
        perms = {str(p): True for p in token}
    elif isinstance(token, str):
        perms = {token: True}
    else:
        # Assume token is an object with an attribute `permissions` that is iterable
        try:
            iterable = getattr(token, "permissions", [])
            perms = {str(p): True for p in iterable}
        except Exception:
            perms = {}

