    def _before_cursor_execute(conn, cursor, statement, parameters, context, executemany):
        # Store a simple trace entry before execution
        conn.info.setdefault("trace", []).append(
            {"phase": "before", "statement": statement, "parameters": parameters}
        )

    def _after_cursor_execute(conn, cursor, statement, parameters, context, executemany):
        # Store a simple trace entry after execution
        conn.info.setdefault("trace", []).append(
            {"phase": "after", "statement": statement, "parameters": parameters}
        )

    event.listen(engine, "before_cursor_execute", _before_cursor_execute)
    event.listen(engine, "after_cursor_execute", _after_cursor_execute)

