def x_forwarded_for(self):
        """X-Forwarded-For header value.

        This is the amended header so that it contains the previous IP address
        in the forwarding change.

        """
        # Retrieve the existing X‑Forwarded‑For header if present
        if hasattr(self, "headers"):
            existing = self.headers.get("X-Forwarded-For")
        elif hasattr(self, "META"):
            existing = self.META.get("HTTP_X_FORWARDED_FOR")
        else:
            existing = None

        # Determine the current client IP address
        if hasattr(self, "remote_addr"):
            current = self.remote_addr
        elif hasattr(self, "META"):
            current = self.META.get("REMOTE_ADDR")
        else:
            current = None

        # Build the amended header value
        parts = []
        if existing:
            parts.append(existing)
        if current:
            parts.append(current)

        return ", ".join(parts) if parts else None

