def DirnamePath(self, path):
    """Determines the directory name of the path.

    The file system root is represented by an empty string.

    Args:
      path (str): path.

    Returns:
      str: directory name of the path or None.
    """
    if not isinstance(path, str):
        return None
    if path == "":
        return ""
    # Remove trailing slashes (except when the path is just "/")
    while path.endswith("/") and path != "/":
        path = path.rstrip("/")
    if path == "":
        return ""
    if "/" not in path:
        return ""
    return path

