def remove(self, uid, filename=None):
        """Remove the Remind command with the uid from the file"""
        if filename is None:
            filename = getattr(self, "filename", None)
            if filename is None:
                raise ValueError("No filename provided and self.filename is not set")
        uid_str = str(uid)
        removed = False
        try:
            with open(filename, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except FileNotFoundError:
            raise
        kept_lines = []
        for line in lines:
            stripped = line.lstrip()
            # Determine the identifier at the start of the line
            first_token = stripped.split(maxsplit=1)[0] if stripped else ""
            if first_token == uid_str:
                removed = True
                continue
            kept_lines.append(line)
        if removed:
            with open(filename, "w", encoding="utf-8") as f:
                f.writelines(kept_lines)
        return removed

