def import_class(name):
    """Load class from fully-qualified python module name.

    ex: import_class('bulbs.content.models.Content')
    """
    import importlib

    parts = name.split('.')
    if len(parts) < 2:
        raise ValueError(f"'{name}' is not a fully-qualified name")
    # Determine module path: longest prefix that can be imported
    for i in range(len(parts) - 1, 0, -1):
        module_name = '.'.join(parts[:i])
        try:
            module = importlib.import_module(module_name)
            attr_parts = parts[i:]
            break
        except ImportError:
            continue
    else:
        raise ImportError(f"Could not import any module from '{name}'")
    obj = module
    for attr in attr_parts:
        try:
            obj = getattr(obj, attr)
        except AttributeError as e:
            raise AttributeError(f"Module '{module_name}' has no attribute '{attr}'") from e
    return obj

