    Retrieve object indexed by <key>
    """
    # Try dictionary-like access first
    if isinstance(self, dict):
        return self[key]

    # Check for a conventional internal storage attribute
    if hasattr(self, "_data"):
        try:
            return self._data[key]
        except (KeyError, TypeError):
            pass

    # Fallback to attribute access (e.g., object fields)
    if hasattr(self, key):
        return getattr(self, key)

    # If all lookups fail, raise KeyError to signal missing key
    raise KeyError(key)

