def get_proxy():
    """Return a random proxy from proxy config."""
    import json, os, random
    from pathlib import Path

    # Try to load proxies from a JSON config file
    config_path = Path(__file__).with_name("proxy_config.json")
    proxies = []
    if config_path.is_file():
        try:
            with config_path.open("r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, list):
                    proxies = [p for p in data if isinstance(p, str) and p]
                elif isinstance(data, dict):
                    # support {"proxies": [...]} format
                    proxies = [p for p in data.get("proxies", []) if isinstance(p, str) and p]
        except Exception:
