def set_spark(cls, master=None, appName=None, conf=None, hive_support=False):
        """Creates and initializes a new `SparkSession`. Argument signature is copied from
        `pyspark.sql.SparkSession
        <https://spark.apache.org/docs/latest/api/python/pyspark.sql.html#pyspark.sql.SparkSession>`_.
        """
        try:
            from pyspark.sql import SparkSession
        except ImportError as e:
            raise ImportError("pyspark is required to create a SparkSession") from e

        builder = SparkSession.builder
        if master is not None:
            builder = builder.master(master)
        if appName is not None:
            builder = builder.appName(appName)
        if conf is not None:
            if not isinstance(conf, dict):
                raise TypeError("conf must be a dict of configuration key/value pairs")
            for k, v in conf.items():
                builder = builder.config(k, v)
        if hive_support:
            builder = builder.enableHiveSupport()
        spark = builder.getOrCreate()
        setattr(cls, "spark", spark)
        return spark

