def wait_for_jobs(jobs):
    """Waits for all the jobs to be runnning.

    Args:
        jobs(list): list of the python-grid5000 jobs to wait for


    Raises:
        Exception: if one of the job gets in error state.
    """
    import time

    if not jobs:
        return

    while True:
        all_running = True
        for job in jobs:
            state = getattr(job, "state", None)
            # Some Grid5000 job objects may have a .status() method returning a dict
            if state is None and callable(getattr(job, "status", None)):
                try:
                    state = job.status().get("state")
                except Exception:
                    state = None
            if state == "error":
                raise Exception(f"Job {getattr(job, 'uid', getattr(job, 'id', 'unknown'))} entered error state")
            if state != "running":
                all_running = False
        if all_running:
            break
        time.sleep(5)

