def authenticate(self, username, password):
        """Authenticates your user and returns an auth token.

        :param str username: Hummingbird username.
        :param str password: Hummingbird password.
        :returns: str -- The Auth Token
        :raises: ValueError -- If the Authentication is wrong
        """
        import requests

        url = getattr(self, "auth_url", "https://hummingbird.me/api/v1/users/auth_token")
        payload = {"username": username, "password": password}
        headers = {"Accept": "application/json"}

        try:
            response = requests.post(url, json=payload, headers=headers, timeout=10)
        except requests.RequestException as exc:
            raise ValueError(f"Authentication request failed: {exc}") from exc

        if response.status_code != 200:
            try:
                error_msg = response.json().get("error", response.text)
            except ValueError:
                error_msg = response.text
            raise ValueError(f"Authentication failed: {error_msg}")

        try:
            data = response.json()
        except ValueError as exc:
            raise ValueError("Invalid response format from authentication endpoint") from exc

        token = data.get("auth_token") or data.get("access_token")
        if not token:
            raise ValueError("Authentication succeeded but token not found in response")
        return token

