def reset(self):
        """Clear the sensorgraph from RAM and flash."""
        # Clear in‑memory structures
        for name in ("graph", "nodes", "edges", "_data", "data"):
            if hasattr(self, name):
                obj = getattr(self, name)
                if isinstance(obj, (dict, list, set)):
                    obj.clear()
                else:
                    try:
                        delattr(self, name)
                    except Exception:
                        setattr(self, name, None)

        # Clear persistent storage if available
        if hasattr(self, "flash"):
            try:
                self.flash.clear()
            except Exception:
                try:
                    self.flash.erase()
                except Exception:
                    pass

