def bfs(self, root = None, display = None):
        """
        API: bfs(self, root = None, display = None)
        Description:
            Searches tree starting from node named root using breadth-first
            strategy if root argument is provided. Starts search from root node
            of the tree otherwise.
        Pre:
            Node indicated by root argument should exist.
        Input:
            root: Starting node name.
            display: Display argument.
        """
        from collections import deque

        # Determine starting node
        if root is None:
            start = getattr(self, "root", None)
            if start is None:
                raise ValueError("Tree has no root node defined.")
        else:
            # Try common accessor methods/attributes to locate the node by name
            if hasattr(self, "search"):
                start = self.search(root)
            elif hasattr(self, "find"):
                start = self.find(root)
            elif hasattr(self, "nodes") and isinstance(self.nodes, dict):
                start = self.nodes.get(root)
            else:
                raise AttributeError("Unable to locate node; provide a valid 'root' name or implement a node lookup method.")
            if start is None:
                raise ValueError(f"Node '{root}' not found in the tree.")

        visited = []
        queue = deque([start])

        while queue:
            node = queue.popleft()
            visited.append(node.name if hasattr(node, "name") else node)

            # Optional display callback
            if display:
                try:
                    display(node)
                except Exception as e:
                    raise RuntimeError(f"Display function raised an exception: {e}")

            # Enqueue children; support common child attributes
            children = []
            if hasattr(node, "children"):
                children = node.children
            elif hasattr(node, "left") or hasattr(node, "right"):
                if getattr(node, "left", None) is not None:
                    children.append

