def _update_tasks_redundancy(config, task_id, redundancy, limit=300, offset=0):
    """Update tasks redundancy from a project."""
    client = config["client"]
    project_id = config.get("project_id")
    if project_id is None:
        raise ValueError("config must contain 'project_id'")
    while True:
        # Retrieve a page of tasks
        tasks_page = client.get_tasks(project_id, limit=limit, offset=offset)
        if not tasks_page:
            break
        for task in tasks_page:
            if str(task.get("id")) == str(task_id):
                # Update the redundancy field for the matching task
                client.update_task(task_id, {"redundancy": redundancy})
                return True
        # Move to next page
        offset += limit
    return False

