def get(self, key, column_path, consistency_level):
    """
    Get the Column or SuperColumn at the given column_path. If no value is present, NotFoundException is thrown. (This is
    the only method that can throw an exception under non-failure conditions.)

    Parameters:
     - key
     - column_path
     - consistency_level
    """
    # Convert key and column_path to bytes if they are strings
    if isinstance(key, str):
        key = key.encode()
    if isinstance(column_path, str):
        column_path = column_path.encode()

    try:
        return self._client.get(key, column_path, consistency_level)
    except NotFoundException:
        # Propagate the expected not‑found exception unchanged
        raise
