def _on_permission_result(self, code, perms, results):
        """ Handles a permission request result by passing it to the
         handler with the given code.

        """
        if len(perms) != len(results):
            raise ValueError("perms and results must have the same length")
        perm_results = dict(zip(perms, results))
        handler = getattr(self, "handler", None)
        if handler is None:
            return
        if hasattr(handler, "on_permission_result"):
            handler.on_permission_result(code, perm_results)
        elif hasattr(handler, "handle_permission_result"):
            handler.handle_permission_result(code, perm_results)
        else:
            try:
                handler(code, perm_results)
            except Exception:
                pass

