def publish(self):
        """
        Publish the current document.

        NOTE: You must have saved any changes to the draft version of the
        document before publishing, unsaved changes wont be published.
        """
        # Ensure there are no pending changes before publishing
        if getattr(self, "_unsaved_changes", False):
            raise RuntimeError("Cannot publish: there are unsaved changes.")
        # The document must have an identifier to be published
        if not hasattr(self, "id"):
            raise AttributeError("Document instance lacks an 'id' attribute required for publishing.")
        # Prefer a custom publish method if the class provides one
        custom_publish = getattr(self, "publish_api", None)
        if callable(custom_publish):
            return custom_publish(self.id)
        # Fallback to a generic API object if present
        api = getattr(self, "api", None)
        if api is not None and hasattr(api, "publish") and callable(api.publish):
            return api.publish(self.id)
        # If no publishing mechanism is available, raise an informative error
        raise NotImplementedError("Publish operation is not implemented for this object.")

