def on_close(self, evt):
    """
    Pop-up menu and wx.EVT_CLOSE closing event
    """
    # Close any open popup menu
    try:
        if hasattr(self, "popup_menu") and self.popup_menu:
            if isinstance(self.popup_menu, wx.Menu):
                self.popup_menu.Destroy()
            else:
                try:
                    self.popup_menu.Hide()
                except Exception:
                    pass
            self.popup_menu = None
    except Exception:
        pass

    # Stop any running timers associated with the window
    if hasattr(self, "timer") and isinstance(self.timer, wx.Timer):
        try:
            if self.timer.IsRunning():
                self.timer.Stop()
        except Exception:
            pass

    # Allow the default close processing (destroy the window)
    try:
        if hasattr(self, "Destroy"):
            self.Destroy()
        else:
            evt.Skip()
    except Exception:
        evt.Skip()

