def is_xml(text):
    """
    Helper function. Lightweight test if response is an XML doc
    """
    import re
    if not isinstance(text, str):
        return False
    s = text.lstrip()
    if not s.startswith('<'):
        return False
    pattern = r'^(<\?xml\s.*?\?>)?\s*<([a-zA-Z_][\w\-.]*)\b[^>]*>.*</\2\s*>'
    return bool(re.search(pattern, s, re.DOTALL))

