def print_generated_sequence(gen, num, *, sep=", ", fmt='', seed=None):
    """
    Helper function which prints a sequence of `num` items
    produced by the random generator `gen`.
    """
    import random

    # Initialize random generator
    rng = random.Random(seed) if seed is not None else random

    # Determine how to obtain values from `gen`
    get_next = None
    if callable(gen):
        # Assume `gen` expects a Random instance
        def get_next():
            return gen(rng)
    elif hasattr(gen, "__next__"):
        def get_next():
            return next(gen)
    else:
        raise TypeError("gen must be a callable or an iterator")

    # Generate and format the sequence
    parts = []
    for _ in range(num):
        val = get_next()
        if fmt:
            try:
                part = format(val, fmt)
            except (ValueError, TypeError):
                part = fmt.format(val)
        else:
            part = str(val)
        parts.append(part)

    # Print the result
    print(sep.join(parts))

