def get(self, key, prompt_default='', prompt_help=''):
        """Return a value from the environ or keyring"""
        import os
        import keyring

        # Try environment variable first
        value = os.getenv(key)
        if value is not None:
            return value

        # Then try keyring if a service name is defined on the instance
        service = getattr(self, "service", None)
        if service:
            try:
                value = keyring.get_password(service, key)
                if value is not None:
                    return value
            except Exception:
                # keyring may not be configured; ignore and fall back to prompting
                pass

        # If we reach here, value is not set; optionally prompt the user
        if prompt_help:
            print(prompt_help)
        prompt = f"{key}"
        if prompt_default:
            prompt += f" [{prompt_default}]"
        prompt += ": "
        try:
            user_input = input(prompt)
        except EOFError:
            user_input = ''
        if not user_input and prompt_default:
            user_input = prompt_default
        return user_input

