def notify(self, resource):
        """
        Notifies the observers of a certain resource.

        :param resource: the resource
        """
        observers = getattr(self, "_observers", None)
        if not observers:
            return
        for observer in observers.get(resource, []):
            try:
                if callable(observer):
                    observer(resource)
                elif hasattr(observer, "update"):
                    observer.update(resource)
                elif hasattr(observer, "notify"):
                    observer.notify(resource)
            except Exception:
                pass

