def matrix_multiply(m1, m2):
    """ Matrix multiplication (iterative algorithm).

    The running time of the iterative matrix multiplication algorithm is :math:`O(n^{3})`.

    :param m1: 1st matrix with dimensions :math:`(n \\times p)`
    :type m1: list, tuple
    :param m2: 2nd matrix with dimensions :math:`(p \\times m)`
    :type m2: list, tuple
    :return: resultant matrix with dimensions :math:`(n \\times m)`
    :rtype: list
    """
    # Validate first matrix dimensions
    if not isinstance(m1, (list, tuple)):
        raise TypeError("m1 must be a list or tuple")
    n = len(m1)
    if n == 0:
        return []
    p = None
    for row in m1:
        if not isinstance(row, (list, tuple)):
            raise TypeError("Rows of m1 must be list or tuple")
        if p is None:
            p = len(row)
            if p == 0:
                raise ValueError("Rows of m1 cannot be empty")
        elif len(row) != p:
            raise ValueError("All rows of m1 must have the same length")
    # Validate second matrix dimensions
    if not isinstance(m2, (list, tuple)):
        raise TypeError("m2 must be a list or tuple")
    if len(m2) != p:
        raise ValueError("Inner matrix dimensions must agree")
    if p == 0:
        return [[] for _ in range(n)]
    m = None
    for row in m2:
        if not isinstance(row, (list, tuple)):
            raise TypeError("Rows of m2 must be list or tuple")
        if m is None:
            m = len(row)
