def get_dimension(geometry):
    """Gets the dimension of a Fiona-like geometry element."""
    type_dim = {
        "Point": 0,
        "MultiPoint": 0,
        "LineString": 1,
        "MultiLineString": 1,
        "Polygon": 2,
        "MultiPolygon": 2,
    }

    geom_type = geometry.get("type")
    if geom_type == "GeometryCollection":
        dims = [
            get_dimension(g) for g in geometry.get("geometries", [])
            if get_dimension(g) is not None
        ]
        return max(dims) if dims else None
    if geom_type in type_dim:
        return type_dim[geom_type]
    raise ValueError(f"Unsupported geometry type: {geom_type}")

