        """ Performs the deduplication and its preliminary checks. """
        # Ensure the object has a 'data' attribute that is iterable
        if not hasattr(self, "data"):
            raise AttributeError("Object must have a 'data' attribute for deduplication.")
        try:
            iterator = iter(self.data)
        except TypeError:
            raise TypeError("'data' attribute must be iterable for deduplication.")

        deduped = []
        seen_hashable = set()
        seen_unhashable = []

        for item in iterator:
            try:
                # Try hashable path
                if item not in seen_hashable:
                    seen_hashable.add(item)
                    deduped.append(item)
            except TypeError:
