def pop(self, key=-1):
    """Removes and returns an item at a given index. Similar to list.pop()."""
    n = len(self)
    if n == 0:
        raise IndexError('pop from empty sequence')
    idx = key
    if idx < 0:
        idx += n
    if idx < 0 or idx >= n:
        raise IndexError('pop index out of range')
    item = self[idx]
    del self[idx]
    return item

