def parse_signed_request(signed_request, app_secret):
    """ Return dictionary with signed request data.

    We return a dictionary containing the information in the
    signed_request. This includes a user_id if the user has authorised
    your application, as well as any information requested.

    If the signed_request is malformed or corrupted, False is returned.

    """
    import base64, hmac, hashlib, json

    if not isinstance(signed_request, str) or '.' not in signed_request:
        return False
    try:
        encoded_sig, encoded_payload = signed_request.split('.', 1)
        # base64url decode helper
        def b64_url_decode(data):
            data = data.replace('-', '+').replace('_', '/')
            padding = '=' * (-len(data) % 4)
            return base64.b64decode(data + padding)

        sig = b64_url_decode(encoded_sig)
        payload = b64_url_decode(encoded_payload)
        expected_sig = hmac.new(
            app_secret.encode('utf-8'), encoded_payload.encode('utf-8'), hashlib.sha256
        ).digest()
        if not hmac.compare_digest(sig, expected_sig):
            return False
        return json.loads(payload.decode('utf-8'))
    except Exception:
        return False

