def fit(self, data):
        """
        Fits a transformer using the SFrame `data`.

        Parameters
        ----------
        data : SFrame
            The data used to fit the transformer.

        Returns
        -------
        self (A fitted object)

        See Also
        --------
        transform, fit_transform
        """
        # Validate input
        try:
            from turicreate import SFrame
        except ImportError:
            raise ImportError("turicreate is required for this transformer.")
        if not isinstance(data, SFrame):
            raise TypeError(f"Expected data to be an SFrame, got {type(data)}")
        # Store column information
        self._column_names = data.column_names()
        self._column_types = {c: data.column_type(c) for c in self._column_names}
        # Compute simple statistics for numeric columns
        self._stats = {}
        for col, typ in self._column_types.items():
            if typ in (int, float):
                col_series = data[col]
                # SFrame column may be None for empty column; guard against it
                if len(col_series) == 0:
                    mean = std = None
                else:
                    mean = col_series.mean()
                    std = col_series.std()
                self._stats[col] = {"mean": mean, "std": std}
            else:
                # For non‑numeric columns store unique values (useful for encoding)
                self._stats[col] = {"unique": data[col].unique()}
        self._fitted = True
        return self

