def __add_introjs_tour_step(self, message, selector=None, name=None,
                                title=None, alignment=None):
        """ Allows the user to add tour steps for a website.
            @Params
            message - The message to display.
            selector - The CSS Selector of the Element to attach to.
            name - If creating multiple tours at the same time,
                   use this to select the tour you wish to add steps to.
            title - Additional header text that appears above the message.
            alignment - Choose from "top", "bottom", "left", and "right".
                        ("top" is the default alignment).
        """
        # Initialize storage for tours if not present
        if not hasattr(self, "_introjs_tours"):
            self._introjs_tours = {}

        # Determine which tour to modify
        tour_name = name if name is not None else "default"

        # Ensure the tour list exists
        if tour_name not in self._introjs_tours:
            self._introjs_tours[tour_name] = []

        # Validate alignment if provided
        if alignment is not None:
            valid_alignments = {"top", "bottom", "left", "right"}
            if alignment not in valid_alignments:
                raise ValueError(
                    f"Invalid alignment '{alignment}'. "
                    f"Choose from {sorted(valid_alignments)}."
                )

        # Build the step dictionary according to intro.js expectations
        step = {"intro": message}
        if selector is not None:
            step["element"] = selector
        if title is not None:
            step["title"] = title
        if alignment is not None:
            step["position"] = alignment

        # Append the step to the selected tour
        self._introjs_tours[tour_name].append(step)

        # Allow method chaining
        return self

