def fetch_archive(savedir, url, fname, checksum, force=False):
    """download an archive to a specific location"""
    import os
    import hashlib
    import urllib.request

    # Ensure the target directory exists
    os.makedirs(savedir, exist_ok=True)
    target_path = os.path.join(savedir, fname)

    def _calc_checksum(path):
        h = hashlib.sha256()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                h.update(chunk)
        return h.hexdigest()

    # Determine if we need to download
    need_download = force
    if not need_download and os.path.isfile(target_path):
        try:
            if _calc_checksum(target_path) == checksum:
                need_download = False
            else:
                need_download = True
        except Exception:
            need_download = True

    if need_download:
        # Download the file
        with urllib.request.urlopen(url) as response, open(target_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)

        # Verify checksum after download
        if _calc_checksum(target_path) != checksum:
            os.remove(target_path)
            raise ValueError(f"Checksum mismatch for downloaded file '{target_path}'")

    return target_path

