def register_entity(self, entity_value, entity_type, alias_of=None, domain=0):
        """
        Register an entity to be tagged in potential parse results.

        Args:
            entity_value(str): the value/proper name of an entity instance
                (Ex: "The Big Bang Theory")
            entity_type(str): the type/tag of an entity instance (Ex: "Television Show")
            domain(str): a string representing the domain you wish to add the entity to
        """
        # Initialize storage structures if they don't exist
        if not hasattr(self, "_entity_registry"):
            self._entity_registry = {}
        if not hasattr(self, "_entity_aliases"):
            self._entity_aliases = {}

        # Normalize domain to a hashable key (allow int or str)
        domain_key = str(domain)

        # Ensure domain dict exists
        domain_dict = self._entity_registry.setdefault(domain_key, {})

        # Ensure type dict exists within the domain
        type_dict = domain_dict.setdefault(entity_type, {})

        # Register the entity value
        if alias_of is None:
            # Direct registration
            type_dict[entity_value] = entity_value
        else:
            # Alias registration: verify the target exists
            target = alias_of
            # Resolve any existing alias chain
            while target in self._entity_aliases:
                target = self._entity_aliases[target]
            # Ensure the target entity is already registered
            found = any(
                target in tdict
                for d in self._entity_registry.values()
                for tdict in d.values()
            )
            if not found:
                raise ValueError(f"Alias target '{alias_of}' is not a registered entity.")
            # Store the alias mapping
            self._entity_aliases[entity_value] = target

