def clear(self, exclude=None):
        """
        Remove all elements in the cache.
        """
        if exclude is None:
            # Remove everything
            try:
                self._cache.clear()
            except AttributeError:
                # Fallback to dict-like behavior
                for key in list(self.__dict__.keys()):
                    del self.__dict__[key]
            return

        # Ensure exclude is a set for fast membership tests
