def _command_callback(self, message):
        """ The callback subscribed to the broker """
        import json
        import logging

        logger = getattr(self, "_logger", logging.getLogger(__name__))

        # Accept both raw MQTTMessage objects (with .payload) and plain dicts
        if hasattr(message, "payload"):
            try:
                payload_data = message.payload.decode("utf-8")
                data = json.loads(payload_data)
            except Exception as exc:
                logger.error("Failed to decode message payload: %s", exc)
                return
        elif isinstance(message, dict):
            data = message
        else:
            logger.error("Unsupported message type: %r", type(message))
            return

        command = data.get("command")
        if not command:
            logger.warning("Received message without 'command' field: %s", data)
            return

        handler_name = f"_handle_{command}"
        handler = getattr(self, handler_name, None)
        if not callable(handler):
            logger.error("No handler found for command '%s'", command)
            return

        try:
            handler(data.get("payload"))
        except Exception as exc:
            logger.exception("Error while handling command '%s': %s", command, exc)

