def exact_or_minor_exe_version_match(executable_name,
                                     exe_version_tuples,
                                     version):
    """
    IF there is an exact match then use it
     OTHERWISE try to find a minor version match
    """
    # Find candidates with matching executable name
    candidates = [t for t in exe_version_tuples if t[0] == executable_name]
    # Exact match
    for exe, ver in candidates:
        if ver == version:
            return (exe, ver)
    # Minor version match (compare first two numeric components)
    target_parts = version.split('.')
    if len(target_parts) < 2:
        target_minor = target_parts[0]
    else:
        target_minor = '.'.join(target_parts[:2])
    for exe, ver in candidates:
        ver_parts = ver.split('.')
        if len(ver_parts) < 2:
            ver_minor = ver_parts[0]
        else:
            ver_minor = '.'.join(ver_parts[:2])
        if ver_minor == target_minor:
            return (exe, ver)
    return None

