def create_upload(self, project_id, path_data, hash_data, remote_filename=None, storage_provider_id=None):
        """
        Create a chunked upload id to pass to create_file_chunk_url to create upload urls.
        :param project_id: str: uuid of the project
        :param path_data: PathData: holds file system data about the file we are uploading
        :param hash_data: HashData: contains hash alg and value for the file we are uploading
        :param remote_filename: str: name to use for our remote file (defaults to path_data basename otherwise)
        :param storage_provider_id: str: optional storage provider id
        :return: str: uuid for the upload
        """
        payload = {
            "project_id": project_id,
            "filename": remote_filename or getattr(path_data, "basename", None),
            "hash": {
                "algorithm": getattr(hash_data, "algorithm", None),
                "value": getattr(hash_data, "value", None),
            },
        }
        if storage_provider_id is not None:
            payload["storage_provider_id"] = storage_provider_id

        # Remove any None values that might have been added unintentionally
        payload = {k: v for k, v in payload.items() if v is not None}
        if "algorithm" in payload["hash"] and payload["hash"]["algorithm"] is None:
            del payload["hash"]["algorithm"]
        if "value" in payload["hash"] and payload["hash"]["value"] is None:
            del payload["hash"]["value"]
        if not payload["hash"]:
            del payload["hash"]

        response = self._post("/uploads", json=payload)
        if not isinstance(response, dict):
            raise TypeError("Expected response to be a dict")
        try:
            return response["upload_id"]
        except KeyError as exc:
            raise KeyError("upload_id not found in response") from exc

