def list_files(self):
        """
        :returns: Array of files in project without temporary files. The files are dictionary {"path": "test.bin", "md5sum": "aaaaa"}
        """
        import os, hashlib

        root = getattr(self, "project_path", getattr(self, "project_root", "."))
        result = []
        temp_exts = (".tmp", ".temp", ".swp", ".bak")
        for dirpath, dirnames, filenames in os.walk(root):
            # skip hidden directories
            dirnames[:] = [d for d in dirnames if not d.startswith('.')]
            for name in filenames:
                if name.startswith('.'):
                    continue
                if name.endswith('~'):
                    continue
                if name.lower().endswith(temp_exts):
                    continue
                full_path = os.path.join(dirpath, name)
                rel_path = os.path.relpath(full_path, root)
                # compute md5
                hash_md5 = hashlib.md5()
                try:
                    with open(full_path, "rb") as f:
                        for chunk in iter(lambda: f.read(8192), b""):
                            hash_md5.update(chunk)
                    md5sum = hash_md5.hexdigest()
                except (OSError, IOError):
                    md5sum = None
                result.append({"path": rel_path, "md5sum": md5sum})
        return result

