def highlight_block(self, text, block):
        """
        Highlights the block using a pygments lexer.

        :param text: text of the block to highlith
        :param block: block to highlight
        """
        from pygments import highlight
        from pygments.lexers import get_lexer_by_name, guess_lexer
        from pygments.formatters import HtmlFormatter

        # Determine language from block if possible
        lang = None
        if isinstance(block, dict):
            lang = block.get("language") or block.get("lang")
        else:
            lang = getattr(block, "language", None) or getattr(block, "lang", None)

        lexer = None
        if lang:
            try:
                lexer = get_lexer_by_name(lang)
            except Exception:
                lexer = None

        if lexer is None:
            try:
                lexer = guess_lexer(text)
            except Exception:
                lexer = None

        if lexer is None:
            # Fallback: return raw text unchanged
            return text

        formatter = HtmlFormatter(nowrap=True)
        return highlight(text, lexer, formatter)

