def _file_details(filename):
    """ Grab the start and end of the file"""
    CHUNK = 1024
    try:
        with open(filename, "rb") as f:
            start = f.read(CHUNK)
            f.seek(0, 2)
            size = f.tell()
            if size <= CHUNK:
                end = start
            else:
                f.seek(-CHUNK, 2)
                end = f.read(CHUNK)
        return start, end
    except Exception:
        return None, None

