mgc_code:
def string_to_identity(identity_str):
    """Parse string into Identity dictionary."""
    import json
    if not identity_str:
        return {}
    # Try JSON parsing
    try:
        data = json.loads(identity_str)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    # Split into key-value pairs
    result = {}
    parts = [p.strip() for p in identity_str.split(',') if p.strip()]
    for part in parts:
        if ':' in part:
            key, val = part.split(':', 1)
        elif '=' in part:
            key, val = part.split('=', 1)
        else:
            continue
        result[key.strip()] = val.strip()
    if result:
        return result
    # Fallback: return raw string under a default key
    return {"identity": identity_str}

