def _to_DOM(self):
        """
        Dumps object data to a fully traversable DOM representation of the
        object.

        :returns: a ``xml.etree.Element`` object

        """
        import xml.etree.ElementTree as ET

        def _serialize_value(parent, name, value):
            """Helper to serialize a value into the XML tree."""
            if hasattr(value, "_to_DOM"):
                # Use the object's own DOM representation
                child = value._to_DOM()
                child.tag = name  # ensure correct tag name
                parent.append(child)
            elif isinstance(value, (list, tuple, set)):
                container = ET.SubElement(parent, name)
                for item in value:
                    _serialize_value(container, "item", item)
            elif isinstance(value, dict):
                container = ET.SubElement(parent, name)
                for k, v in value.items():
                    _serialize_value(container, str(k), v)
            else:
                # Primitive types – store as text
                elem = ET.SubElement(parent, name)
                elem.text = "" if value is None else str(value)

        # Create root element named after the class
        root = ET.Element(self.__class__.__name__)

