def mongodb_ensure_index(database_name, collection_name, key):
    """Ensure Index"""
    from pymongo import MongoClient

    client = MongoClient()
    try:
        db = client[database_name]
        coll = db[collection_name]

        # Normalize key to the format accepted by create_index
        if isinstance(key, str):
            index_key = [(key, 1)]
        elif isinstance(key, dict):
            index_key = list(key.items())
        else:
            index_key = key  # assume already in correct format (list/tuple)

        return coll.create_index(index_key)
