def unpack_bytes(self, obj_bytes, encoding=None):
        """Unpack a byte stream into a dictionary."""
        import json, pickle
        # If encoding is specified, assume a text-based format (JSON)
        if encoding is not None:
            try:
                text = obj_bytes.decode(encoding)
                data = json.loads(text)
                if not isinstance(data, dict):
                    raise ValueError("Decoded JSON is not a dictionary")
                return data
            except Exception as e:
                raise ValueError(f"Failed to decode bytes with encoding '{encoding}': {e}")

        # No encoding: try binary pickle first
        try:
            data = pickle.loads(obj_bytes)
            if isinstance(data, dict):
                return data
        except Exception:
            pass

        # Fallback to JSON assuming UTF-8
        try:
            text = obj_bytes.decode('utf-8')
            data = json.loads(text)
            if not isinstance(data, dict):
                raise ValueError("Decoded JSON is not a dictionary")
            return data
        except Exception as e:
            raise ValueError(f"Unable to unpack bytes into a dictionary: {e}")

