def expand_variables(self, variables):
        """Expand variables in policy data.

        Updates the policy data in-place.
        """
        import re

        # Determine the attribute that holds the policy data
        policy = (
            getattr(self, "policy", None)
            or getattr(self, "policy_data", None)
            or getattr(self, "data", None)
        )
        if policy is None:
            raise AttributeError("No policy data attribute found on the object.")

        var_pattern = re.compile(r"\$\{([^}]+)\}")

