def change_frozen_attr(self):
        """Changes frozen state of cell if there is no selection"""
        # If there is any selection, do nothing
        if getattr(self, "selection", None):
            return

        # Determine the target cell (fallback to a generic 'cell' attribute)
        cell = getattr(self, "current_cell", None) or getattr(self, "cell", None)
        if cell is None:
            return

        # Toggle the frozen attribute if it exists, otherwise create it as True
        if hasattr(cell, "frozen"):
            cell.frozen = not cell.frozen
        else:
            setattr(cell, "frozen", True)

