def start(self, nb_threads: int) -> None:
        """Should only be called once all the jobs have been added using add_job().
        """
        import threading, queue

        if getattr(self, "_started", False):
            raise RuntimeError("start() has already been called")
        self._started = True

        # Ensure a job queue exists
        if not hasattr(self, "_job_queue"):
            self._job_queue = queue.Queue()
        self._job_queue = getattr(self, "_job_queue")

        # Event to signal workers to stop (if needed later)
        self._stop_event = threading.Event()

        def _worker():
            while not self._stop_event.is_set():
                try:
                    job = self._job_queue.get(timeout=0.1)
                except queue.Empty:
                    continue
                try:
                    job()
                except Exception:
                    # Swallow exceptions from jobs to keep the thread alive
                    pass
                finally:
                    self._job_queue.task_done()

        self._threads = []
        for _ in range(nb_threads):
            t = threading.Thread(target=_worker, daemon=True)
            t.start()

