            if callable(perms):
                own_perms = set(perms(actor))
            else:
                own_perms = set(perms)
        else:
            own_perms = set()

        # Resolve inherited permissions if not supplied
        if inherited is None:
            parent = getattr(self, "parent", None)
            if parent is not None:
                inherited = parent.permissions(actor)
            else:
                inherited = set()
        else:
            inherited = set(inherited)

        return own_perms.union(inherited)

