def _set_repository_view(self, session):
        """Sets the underlying repository view to match current view"""
        # Identify the model class that represents the repository.
        model = getattr(self, "repository_model", None)
        if model is None:
            raise AttributeError("Missing 'repository_model' attribute on the instance")

        # Start a query for the model.
        query = session.query(model)

        # Apply any view filters defined on the instance.
        view = getattr(self, "view", None)
        if view:
            if isinstance(view, dict):
                query = query.filter_by(**view)
            else:
                # Assume an iterable of SQLAlchemy filter expressions.
                for condition in view:
                    query = query.filter(condition)

        # Execute the query and store the result as the current repository view.
        self._repository_view = list(query)
        return self._

