def compiler():
    """Get compiler to use for C++ to binary process. The precedence for
    choosing the compiler is as follows::

      1. `CXX` environment variable
      2. User configuration (~/.pythranrc)

    Returns None if none is set or if it's set to the empty string

    """
    import os

    # Check environment variable
    env_compiler = os.getenv("CXX")
    if env_compiler:
        return env_compiler

    # Check user configuration file
    rc_path = os.path.expanduser("~/.pythranrc")
    if not os.path.isfile(rc_path):
        return None

    try:
        with open(rc_path, "r", encoding="utf-8") as rc_file:
            for line in rc_file:
                line = line.split("#", 1)[0].strip()  # remove comments
                if not line:
                    continue
                if "=" in line:
                    key, value = line.split("=", 1)
                    if key.strip() == "CXX":
                        value = value.strip()
                        return value if value else None
    except OSError:
        return None

    return None

