def load():
    """ Check available plugins and attempt to import them """
    import importlib
    import pkgutil

    plugins = {}
    # Determine the plugins package relative to this module
    if "." in __name__:
        base_pkg = __name__.rsplit(".", 1)[0]
        plugins_pkg_name = f"{base_pkg}.plugins"
    else:
        plugins_pkg_name = "plugins"

    try:
        plugins_pkg = importlib.import_module(plugins_pkg_name)
    except ImportError:
        return plugins

    for _, mod_name, is_pkg in pkgutil.iter_modules(plugins_pkg.__path__):
        if is_pkg:
            continue
        full_name = f"{plugins_pkg_name}.{mod_name}"
        try:
            mod = importlib.import_module(full_name)
            plugins[mod_name] = mod
        except Exception:
            # Silently ignore plugins that fail to import
            continue

    return plugins

