def _superclasses_for_subject(self, graph, typeof):
        """helper, returns a list of all superclasses of a given class"""
        from rdflib.namespace import RDFS

        visited = set()
        superclasses = []

        def _collect(cls):
            for sup in graph.objects(cls, RDFS.subClassOf):
                if sup not in visited:
                    visited.add(sup)
                    superclasses.append(sup)
                    _collect(sup)

        _collect(typeof)
        return superclasses

