    """
    Handle py3-cmd list and docstring options.
    """
    import ast, textwrap
    # If the input is already a list or tuple, return a list copy
    if isinstance(sps, (list, tuple)):
        return list(sps)

    # If the input is a string that looks like a Python literal list, try to evaluate it
    if isinstance(sps, str):
        stripped = sps.strip()
        # Quick check for list-like syntax
        if stripped.startswith('[') and stripped.endswith(']'):
            try:
                parsed = ast.literal_eval(stripped)
                if isinstance(parsed, (list, tuple)):
                    return list(parsed)
            except Exception:
