def _readoct(self, length, start):
        """Read bits and interpret as an octal string."""
        if length <= 0:
            return ''
        # Obtain integer value of the specified bits
        if hasattr(self, "_readbits"):
            value = self._readbits(length, start)
        else:
            # Fallback: assume a binary string attribute named `_bits`
            bits = getattr(self, "_bits", "")
            slice_ = bits[start:start + length]
            value = int(slice_, 2) if slice_ else 0
        # Compute required octal digit count (3 bits per octal digit)
        oct_digits = (length + 2) // 3
        # Format with leading zeros to preserve length
        return format(value, f'0{oct_digits}o')

