def add_option(self, key, default=NO_VALUE, alternate_keys=NO_VALUE,
                   doc='', parser=str, **meta):
        """Add an option to the group.

        :arg key: the key to look up

        :arg default: the default value (if any); must be a string that is
            parseable by the specified parser

        :arg alternate_keys: the list of alternate keys to look up;
            supports a ``root:`` key prefix which will cause this to look at
            the configuration root rather than the current namespace

        :arg doc: documentation for this config option

        :arg parser: the parser for converting this value to a Python object

        :arg meta: catch-all for other key/value pairs you want to association
            with this option

        """
        # Ensure internal storage exists
        if not hasattr(self, '_options'):
            self._options = {}
        # Validate key
        if key in self._options:
            raise ValueError(f"Option '{key}' already defined")
        # Process default
        if default is not NO_VALUE:
            try:
                parsed_default = parser(default)
            except Exception as exc:
                raise ValueError(f"Default value for '{key}' cannot be parsed: {exc}") from exc
        else:
            parsed_default = NO_VALUE
        # Process alternate keys
        if alternate_keys is NO_VALUE:
            alt_keys = []
        else:
            if isinstance(alternate_keys, (list, tuple, set)):
                alt_keys = list(alternate_keys)
            else:
                alt_keys = [alternate_keys]
        # Store the option definition
        self._options[key] = {
            'key': key,
            'default': parsed_default,
            'alternate_keys': alt_keys,
            'doc': doc,
            'parser': parser,
            'meta': meta,
        }

