def distance_between(self, from_obj, to_obj, limit=2):
        """
        Calculates the distance between two objects. Distance 0 means
        ``from_obj`` and ``to_obj`` are the same objects, 1 means ``from_obj``
        has a direct connection to ``to_obj``, 2 means that one or more of
        ``from_obj``'s connected objects are directly connected to ``to_obj``,
        etc.

        ``limit`` limits the depth of connections traversal.

        Returns ``None`` if the two objects are not connected within ``limit``
        distance.
        """
        from collections import deque

        # Helper to retrieve connections of an object; defaults to empty iterable.
        def _get_connections(obj):
            # Common attribute names for adjacency lists.
            for attr in ("connections", "connected", "neighbors", "edges"):
                if hasattr(obj, attr):
                    return getattr(obj, attr)
            # Fallback to a method that returns connections.
            if hasattr(obj, "get_connections"):
                return obj.get_connections()
            return ()

        if from_obj is to_obj:
            return 0

        visited = {from_obj}
        queue = deque([(from_obj, 0)])

        while queue:
            current, dist = queue.popleft()
            if dist >= limit:
                continue
            next_dist = dist + 1
            for neighbor in _get_connections(current):
                if neighbor is to_obj:
                    return next_dist
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, next_dist))

        return None

