def delete_many(cls, documents):
        """Delete multiple documents"""
        # Ensure the class has a `collection` attribute (e.g., a pymongo Collection)
        if not hasattr(cls, "collection"):
            raise AttributeError(f"{cls.__name__} missing required 'collection' attribute")
        # Normalise input: accept a list of ids or a list of documents containing an `_id` field
        ids = []
        for doc in documents:
            if isinstance(doc, dict) and "_id" in doc:
                ids.append(doc["_id"])
            else:
                ids.append(doc)
        if not ids:
            return 0
        # Perform bulk delete using the `$in` operator
        result = cls.collection.delete_many({"_id": {"$in": ids}})
        # Return the number of documents actually removed
        return result.deleted_count

