def write_image(filename, image):
    """ Write image data to PNG, JPG file

    :param filename: name of PNG or JPG file to write data to
    :type filename: str
    :param image: image data to write to file
    :type image: numpy array
    """
    import os
    from PIL import Image
    import numpy as np

    if not isinstance(filename, str):
        raise TypeError("filename must be a string")
    if not isinstance(image, np.ndarray):
        raise TypeError("image must be a numpy array")

    # Determine image mode
    if image.ndim == 2:
        mode = "L"
    elif image.ndim == 3:
        if image.shape[2] == 3:
            mode = "RGB"
        elif image.shape[2] == 4:
            mode = "RGBA"
        else:
            raise ValueError("Unsupported channel count: {}".format(image.shape[2]))
    else:
        raise ValueError("Unsupported image dimensions: {}".format(image.shape))

    # Ensure data type is uint8 for Pillow
    if image.dtype != np.uint8:
        image = (255 * (image - image.min()) / (image.max() - image.min() + 1e-12)).astype(np.uint8)

    # Create Pillow image
    pil_img = Image.fromarray(image, mode)

    # Determine format from file extension
    _, ext = os.path.splitext(filename)
    ext = ext.lower()
    if ext in (".png",):
        fmt = "PNG"

