def unblock_ip(ip_address, pipe=None):
    """ unblock the given IP """
    import subprocess

    cmd = ["iptables", "-D", "INPUT", "-s", ip_address, "-j", "DROP"]
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        if pipe is not None:
            pipe.write(result.stdout)
            pipe.write(result.stderr)
        return result.returncode == 0
    except FileNotFoundError:
        if pipe is not None:
            pipe.write("iptables command not found\n")
        return False
    except Exception as e:
        if pipe is not None:
            pipe.write(f"Error: {e}\n")
        return False

