def delete(self, model_name):
    """Delete a model.

    Args:
      model_name: the name of the model. It can be a model full name
          ("projects/[project_id]/models/[model_name]") or just [model_name].
    """
    # Determine full resource name
    if '/' not in model_name:
        # Assume the instance has `project` and `location` attributes
        if not hasattr(self, "project") or not hasattr(self, "location"):
            raise ValueError(
                "Model name must be a full resource name or the instance must have "
                "`project` and `location` attributes to build one."
            )
        full_name = f"projects/{self.project}/locations/{self.location}/models/{model_name}"
    else:
        full_name = model_name

    # Call the underlying client to delete the model
    if not hasattr(self, "client"):
        raise AttributeError("The object does not have a `client` attribute for API calls.")
    operation = self.client.delete_model(name=full_name)

