def get_kl_loss(self, means, log_vars, means_p=None, log_vars_p=None):
    """Get KL loss for all the predicted Gaussians."""
    import torch

    if means_p is None:
        means_p = torch.zeros_like(means)
    if log_vars_p is None:
        log_vars_p = torch.zeros_like(log_vars)

    var = torch.exp(log_vars)
    var_p = torch.exp(log_vars_p)

    # KL divergence per element
    kl_elem = 0.5 * (
        (var + (means - means_p) ** 2) / var_p
        - 1
        + log_vars_p
        - log_vars
    )

    # Sum over latent dimensions (assumes last dimension holds them)
    kl_per_sample = kl_elem.sum(dim=-1)

    # Return mean KL over the batch
    return kl_per_sample.mean()

