def strip_errors(obj):
    """
    Reads through and error object and replaces the error dict with the
    value

    args:
        obj: the error object/dictionary
    """
    if isinstance(obj, dict):
        # If this dict represents an error with a 'value', replace it
        if "error" in obj and "value" in obj and len(obj) == 2:
            return obj["value"]
        # Otherwise, recurse into each value
        return {k: strip_errors(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        processed = [strip_errors(item) for item in obj]
        return type(obj)(processed)
    return obj

