def receive(self,message_type):
        """
        Receive the message of the specified type and retun

            Args:
                - message_type: the type of the message to receive

            Returns:
                - the topic of the message
                - the message received from the socket
        """
        while True:
            # Receive a multipart message: [topic, payload]
            try:
                parts = self.socket.recv_multipart()
            except Exception as e:
                raise RuntimeError(f"Failed to receive message: {e}")

            if not parts:
                continue

            # Ensure we have at least a topic and a payload
            if len(parts) < 2:
                continue

            topic_bytes, payload = parts[0], parts[1]

            try:
                topic = topic_bytes.decode('utf-8')
            except Exception:
                topic = topic_bytes

            # If a specific message_type is requested, filter accordingly
            if message_type is not None and topic != message_type:
                continue

            # Decode payload if possible, otherwise return raw bytes
            try:
                message = payload.decode('utf-8')
            except Exception:
                message = payload

            return topic, message

