async def awaitable_runner(runner: BaseRunner):
    """Execute a runner without blocking the event loop"""
    import asyncio
    import inspect

    run_method = getattr(runner, "run", None)
    if run_method is None:
        raise AttributeError("Runner object must have a 'run' method")

    if inspect.iscoroutinefunction(run_method):
        return await run_method()
    return await asyncio.to_thread(run_method)

