def nearest_interval(self, interval):
        """
        This function returns the nearest interval to any given interval.
        """
        # Assume self.intervals is an iterable of (start, end) tuples
        if not hasattr(self, "intervals") or not self.intervals:
            return None

        a_start, a_end = interval
        # Ensure proper ordering
        if a_start > a_end:
            a_start, a_end = a_end, a_start

        def _distance(b):
            b_start, b_end = b
            if b_start > b_end:
                b_start, b_end = b_end, b_start
            # Overlap -> distance 0
            if not (a_end < b_start or b_end < a_start):
                return 0
            # Non‑overlapping
            if a_end < b_start:
                return b_start - a_end
            else:  # b_end < a_start
                return a_start - b_end

        nearest = None
        min_dist = None
        for cand in self.intervals:
            d = _distance(cand)
            if min_dist is None or d < min_dist:
                min_dist = d
                nearest = cand

