def process_ip_frame(self,
                         id=None,
                         msg=None):
        """process_ip_frame

        Convert a complex nested json dictionary
        to a flattened dictionary and capture
        all unique keys for table construction

        :param id: key for this msg
        :param msg: ip frame for packet
        """
        if msg is None:
            return {}
        # Ensure a set exists to store unique keys
        if not hasattr(self, 'keys'):
            self.keys = set()
        def _flatten(obj, parent_key=''):
            items = {}
            if isinstance(obj, dict):
                for k, v in obj.items():
                    new_key = f"{parent_key}_{k}" if parent_key else k
                    items.update(_flatten(v, new_key))
            elif isinstance(obj, list):
                for idx, v in enumerate(obj):
                    new_key = f"{parent_key}_{idx}" if parent_key else str(idx)
                    items.update(_flatten(v, new_key))
            else:
                items[parent_key] = obj
            return items
        flat = _flatten(msg)
        # Include the provided id if given
        if id is not None:
            flat['id'] = id
        # Update the set of unique keys
        self.keys.update(flat.keys())
        return flat

