def load(*, name="dummy", options={}, dry_run=False, **kwargs):
    """
    Load a backup driver

    :param name(str, optional): name of the backup driver to load
    :param options(dict, optional): A dictionary passed to the driver
    :param dry_run(bool, optional): Whether to activate dry run mode
    :param \*\*kwargs: arbitrary keyword arguments
    :raises ValueError: if specified driver does not exist
    """
    import importlib

    try:
        module = importlib.import_module(name)
    except ImportError as exc:
        raise ValueError(f"Driver '{name}' does not exist") from exc

    driver_cls = getattr(module, "Driver", None)
    if driver_cls is None:
        if callable(module):
            driver_cls = module
        else:
            raise ValueError(f"Driver '{name}' does not expose a Driver class or callable")

    # Ensure we don't mutate the caller's dict
    opts = dict(options) if options else {}
    return driver_cls(options=opts, dry_run=dry_run, **kwargs)

