def parse_for_download(args):
    """
    Turn an argument such as 4, 6-8, 10 into a list such as [4,6,7,8,10]
    """
    parts = [p.strip() for p in str(args).split(',') if p.strip()]
    result = []
    for part in parts:
        if '-' in part:
            start_str, end_str = part.split('-', 1)
            try:
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                continue
            if start <= end:
                result.extend(range(start, end + 1))
            else:
                result.extend(range(start, end - 1, -1))
        else:
            try:
                result.append(int(part))
            except ValueError:
                continue
    return result

