def get(self, section, key):
        """get function reads the config value for the requested section and
        key and returns it

        Parameters:
            * **section (string):** the section to look for the config value either - oxd, client
            * **key (string):** the key for the config value required

        Returns:
            **value (string):** the function returns the value of the key in the appropriate format if found or returns None if such a section or key couldnot be found

        Example:
            config = Configurer(location)
            oxd_port = config.get('oxd', 'port')  # returns the port of the oxd
        """
        # Determine the underlying configuration storage
        cfg = None
        if hasattr(self, "config"):
            cfg = getattr(self, "config")
        elif hasattr(self, "_config"):
            cfg = getattr(self, "_config")
        elif hasattr(self, "settings"):
            cfg = getattr(self, "settings")
        if cfg is None:
            return None

        # If the config is a dict‑of‑dicts
        if isinstance(cfg, dict):
            section_dict = cfg.get(section)
            if isinstance(section_dict, dict):
                return section_dict.get(key)
            return None

        # If the config follows the ConfigParser API
        try:
            import configparser
        except Exception:
            configparser = None

        if configparser and hasattr(cfg, "get"):
            try:
                # ConfigParser may raise specific exceptions
                return cfg.get(section, key)
            except (configparser.NoSectionError, configparser.NoOptionError, KeyError, TypeError):
                return None

        # Fallback: try attribute access (e.g., objects with sections as attributes)
        try:
            sec = getattr(cfg, section)
            return getattr(sec, key, None)
        except Exception:
            return None

