def lastmod(self, category):
        """Return the last modification of the entry."""
        # Attempt to retrieve a modifications mapping from common attribute names
        mods = getattr(self, "_modifications", None)
        if mods is None:
            mods = getattr(self, "modifications", None)

        # If a mapping is found, look up the category
        if isinstance(mods, dict):
            val = mods.get(category)
            if isinstance(val, (list, tuple)):
                # Return the most recent entry (assumes comparable timestamps)
                return max(val) if val else None
            return val

        # Fallback: look for a dedicated attribute like "<category>_lastmod"
        attr_name = f"{category}_lastmod"
        if hasattr(self, attr_name):
            return getattr(self, attr_name)

        # No modification information available for the given category
        return None

