    try:
        # Most backends accept configuration as keyword arguments.
        return backend_cls(**config)
    except TypeError:
        try:
            # Fallback: pass the whole config as a single positional argument.
            return backend_cls(config)
        except Exception as exc:
            raise TypeError(
                f"Failed to instantiate backend '{backend_path}' with provided settings"
