        """Clean title with the use of og:site_name
        in this case try to get rid of site name
        and use TITLE_SPLITTERS to reformat title
        """
        if not title:
            return ''
        site = getattr(self, 'og_site_name', None)
        if site:
            title = title.replace(site, '')
        title = ' '.join(title.split())
        best = title
        for splitter in TITLE_SPLITTERS:
            parts = [p.strip() for p in title.split(splitter) if p.strip()]
            if parts:
                candidate = max(parts, key=len)
                if len(candidate) > len(best):
                    best = candidate
        return best

