def get_subgraph_from_edge_list(graph, edge_list):
    """Transforms a list of edges into a subgraph."""
    # Filter edges that actually exist in the original graph
    valid_edges = []
    for e in edge_list:
        # Support (u, v) or (u, v, data) tuples
        if len(e) >= 2:
            u, v = e[0], e[1]
            if graph.has_edge(u, v):
                valid_edges.append(e)
    # Create a subgraph containing only the valid edges
    subgraph = graph.edge_subgraph(valid_edges).copy()
    return subgraph

