def checkOneValue(self,v,strict=0):
        """Checks a single value to see if it is in range or choice list

        Allows indirection strings starting with ")".  Assumes
        v has already been converted to right value by
        _coerceOneValue.  Returns value if OK, or raises
        ValueError if not OK.
        """
        # Allow indirection strings that start with ')'
        if isinstance(v, str) and v.startswith(')'):
            return v

        # If a range is defined, ensure the value falls within it
        rng = getattr(self, 'range', None)
        if rng is not None:
            if not (len(rng) == 2):
                raise ValueError(f"Invalid range definition on {self!r}: {rng}")
            lo, hi = rng
            try:
                if not (lo <= v <= hi):
                    raise ValueError
            except TypeError:
                raise ValueError(f"Value {v!r} is not comparable with range {rng!r}")
            return v

        # If a list of choices is defined, ensure the value is one of them
        choices = getattr(self, 'choices', None)
        if choices is not None:
            if v not in choices:
                raise ValueError(f"Value {v!r} not in allowed choices {choices!r}")

