def _get_acronyms(acronyms):
    """Return a formatted list of acronyms."""
    # Normalize input to a list of strings, strip whitespace, uppercase, and remove duplicates while preserving order
    seen = set()
    formatted = []
    for item in acronyms or []:
        if not isinstance(item, str):
            continue
        acronym = item.strip().upper()
        if acronym and acronym not in seen:
            seen.add(acronym)
            formatted.append(acronym)
    return formatted

