def latinize(mapping, bind, values):
    """ Transliterate a given string into the latin alphabet. """
    result_parts = []
    # Helper to transliterate a single string
    def transliterate(s):
        return ''.join(mapping.get(ch, ch) for ch in s)
    # If values is a single string, treat it as one element
    if isinstance(values, str):
        return transliterate(values)
    # Otherwise, assume it's an iterable of strings
    for val in values:
        if not isinstance(val, str):
            raise TypeError("Each value must be a string")
        result_parts.append(transliterate(val))
    return bind.join(result_parts)

