def get_event(self, wait=0.25, tag='', full=False):
        """
        Get a single salt event.
        If no events are available, then block for up to ``wait`` seconds.
        Return the event if it matches the tag (or ``tag`` is empty)
        Otherwise return None

        If wait is 0 then block forever or until next event becomes available.
        """
        import queue
        q = getattr(self, "_event_queue", None)
        if q is None:
            raise AttributeError("Instance lacks '_event_queue' attribute")
        if wait == 0:
            event = q.get()
        else:
            try:
                event = q.get(timeout=wait)
            except queue.Empty:
                return None
        if tag and event.get("tag") != tag:
            return None
        return event if full else event.get("data")

