def zcr(data):
    """Computes zero crossing rate of segment"""
    n = len(data)
    if n < 2:
        return 0.0
    try:
        import numpy as np
        arr = np.asarray(data, dtype=float)
        prod = arr[1:] * arr[:-1]
        crossings = np.sum(prod < 0)
        return float(crossings) / (n - 1)
