        if hasattr(pool, "size"):
            size_attr = getattr(pool, "size")
            return size_attr() if callable(size_attr) else size_attr
        # Fallback to length of container
        if hasattr(pool, "__len__"):
            return len(pool)
        raise TypeError(f"Cannot determine size of pool {pid!r}")

