def tt(self, key, locale=None, locale2=None, default=I18n.DFT):
        """
        |tt| means text transform.

        key: tt key.
        locale: main locale key into |self.tt_dd|. Default to |self.locale|
        locale2: fallback locale key into |self.tt_dd|. Default to |self.locale2|
        default: a default value in case tt value is not found. Default to raise KeyError.
        """
        if locale is None:
            locale = getattr(self, "locale", None)
        if locale2 is None:
            locale2 = getattr(self, "locale2", None)

        # Try primary locale
        primary_dict = self.tt_dd.get(locale, {}) if locale is not None else {}
        if key in primary_dict:
            return primary_dict[key]

        # Try fallback locale
        if locale2 is not None:
            fallback_dict = self.tt_dd.get(locale2, {})
            if key in fallback_dict:
                return fallback_dict[key]

        # Return default or raise
        if default is I18n.DFT:
            raise KeyError(key)
        return default

