def start(self):
        """
        Should be called from main thread
        :return:
        """
        import threading
        if threading.current_thread().name != "MainThread":
            raise RuntimeError("start() must be called from the main thread")
        if getattr(self, "_running", False):
            return
        self._running = True

        def _target():
            try:
                if hasattr(self, "run"):
                    self.run()
            finally:
                self._running = False

        self._thread = threading.Thread(target=_target, daemon=True)
        self._thread.start()

