def _mem(self):
        """Record Memory usage."""
        try:
            import psutil
            mem = psutil.Process().memory_info().rss
        except Exception:
            import resource, os
            usage = resource.getrusage(resource.RUSAGE_SELF)
            # ru_maxrss is in kilobytes on Linux/macOS, bytes on some systems
