def uniform_crossover(parents):
    """Perform uniform crossover on two parent chromosomes.

    Randomly take genes from one parent or the other.
    Ex. p1 = xxxxx, p2 = yyyyy, child = xyxxy
    """
    import random
    if not isinstance(parents, (list, tuple)) or len(parents) != 2:
        raise ValueError("parents must be a sequence of exactly two parent chromosomes")
    p1, p2 = parents
    if len(p1) != len(p2):
        raise ValueError("parent chromosomes must be of equal length")
    child_genes = [random.choice((p1[i], p2[i])) for i in range(len(p1))]
    try:
        return type(p1)(child_genes)
    except Exception:
        # Fallback for types that cannot be constructed directly from a list (e.g., strings)
        if isinstance(p1, str):
            return ''.join(child_genes)
        return child_genes

