def clear( self ):
        """
        Clears out all of the rollout items from the widget.
        """
        # Remove all child widgets from the layout (if any)
        layout = getattr(self, 'layout', None)
        if callable(getattr(layout, 'takeAt', None)):
            while layout.count():
                item = layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.setParent(None)
                    try:
                        widget.deleteLater()
                    except Exception:
                        pass

        # Clear any internal collection of rollout items
        for attr in ('rollout_items', '_rollout_items', 'items'):
            if hasattr(self, attr):
                collection = getattr(self, attr)
                if isinstance(collection, (list, dict, set)):
                    if isinstance(collection, dict):
                        collection.clear()
                    else:
                        collection[:] = [] if isinstance(collection, list) else set()
                else:
                    # Fallback: just delete the attribute
                    delattr(self, attr)

