def is_fresh(self, freshness):
        """Return False if given freshness value has expired, else True."""
        import datetime, time
        if freshness is None:
            return False
        # If freshness is a datetime, compare with current time
        if isinstance(freshness, datetime.datetime):
            now = datetime.datetime.utcnow()
            if freshness.tzinfo is not None:
                now = datetime.datetime.now(freshness.tzinfo)
            return freshness >= now
        # If freshness is a numeric timestamp (seconds since epoch)
        try:
            return float(freshness) >= time.time()
        except Exception:
            # Unsupported type; consider it expired
            return False

